//! What the structure, MEP and family commands share: where each category's types live, the
//! library kinds that name them, and making a new element.

use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use std::cell::Cell;

pub type R<T> = Result<T, String>;

/// The categories that are runs: a straight element from `start` to `end` of a type with a section.
pub const RUN_CATS: &[&str] = &[
    "beam",
    "stripfooting",
    "pipe",
    "duct",
    "conduit",
    "cabletray",
    "wire",
    "downconductor",
    "groundconductor",
    "cable",
];

/// The categories that are columns (a plan outline, a base, a height).
pub const COLUMN_CATS: &[&str] = &["column", "structuralcolumn", "footing"];

pub fn is_run(cat: &str) -> bool {
    RUN_CATS.contains(&cat)
}

/// The library kind of a category's types: `type:beam`, `type:structuralcolumn`…
pub fn type_kind(cat: &str) -> String {
    format!("type:{}", cat)
}

/// Where a category's types are in the project file's `types`: (section, sub-key for runs).
pub fn type_path(cat: &str) -> (&'static str, Option<&'static str>) {
    if let Some(c) = RUN_CATS.iter().find(|c| **c == cat) {
        return ("runs", Some(c));
    }
    let sec = match cat {
        "wall" => "wall",
        "floor" => "floor",
        "door" => "door",
        "window" => "window",
        "column" => "column",
        "roof" => "roof",
        "ceiling" => "ceiling",
        "railing" => "railing",
        "structuralcolumn" => "structural_column",
        "footing" => "footing",
        _ => "",
    };
    (sec, None)
}

/// A category's types by name (None when the project has none of it).
pub fn types_of<'a>(pr: &'a Project, cat: &str) -> Option<&'a Map> {
    let (sec, sub) = type_path(cat);
    if sec.is_empty() {
        return None;
    }
    let t = pr.section("types")?.get(sec)?;
    match sub {
        Some(k) => t.get(k)?.as_obj(),
        None => t.as_obj(),
    }
}

/// One type of a category, by name.
pub fn type_of<'a>(pr: &'a Project, cat: &str, name: &str) -> Option<&'a Value> {
    types_of(pr, cat)?.get(name)
}

/// The name of the type of a category with this GUID.
pub fn type_name_of_guid(pr: &Project, cat: &str, g: &str) -> Option<String> {
    let id = pr.lib_find_guid(g)?;
    let e = pr.library.get(&id)?;
    if e.get("kind").and_then(|k| k.as_str()) != Some(type_kind(cat).as_str()) {
        return None;
    }
    e.get("name").and_then(|n| n.as_str()).map(|s| s.to_string())
}

/// The GUID of a category's type by name.
pub fn type_guid(pr: &Project, cat: &str, name: &str) -> Option<String> {
    pr.lib_guid(&type_kind(cat), name)
}

/// The type an element of a category refers to (by its `type` GUID): (name, type value).
pub fn element_type<'a>(pr: &'a Project, e: &Value) -> Option<(String, &'a Value)> {
    let cat = e.get("category")?.as_str()?;
    let g = e.get("type")?.as_str()?;
    let name = type_name_of_guid(pr, cat, g)?;
    let t = type_of(pr, cat, &name)?;
    Some((name, t))
}

/// Puts a new element in the project under a fresh id: stamped with the session's phase and
/// design option (as every new element is), and returns its id. `e` is the element as the file
/// holds it, its `guid` first.
pub fn add_element(s: &mut Session, mut e: Value) -> u64 {
    crate::styles::phasing::stamp_new(&s.project, s.now_phase.as_deref(), s.now_option.as_deref(), &mut e);
    let id = s.project.alloc_id();
    s.project.elements.insert(id, e);
    id
}

/// A new GUID.
pub fn new_guid() -> String {
    crate::rand::guid()
}

thread_local! {
    /// Set by a command that makes an undo step even where the model is as it was.
    static STEP: Cell<bool> = const { Cell::new(false) };
}

/// A command of this module says it makes an undo step whether or not the model changed.
pub fn mark_step() {
    STEP.with(|s| s.set(true));
}

pub fn clear_step() {
    STEP.with(|s| s.set(false));
}

pub fn step_marked() -> bool {
    STEP.with(|s| s.get())
}
//! Structure, MEP and families: columns, footings, beams, runs (pipes, ducts, conduits, trays, wires, conductors, cabling), rebar and reinforce, types, families and components, and the sizing calculators.

pub mod calc;
pub mod common;
pub mod component;
pub mod family;
pub mod formula;
pub mod members;
pub mod rebar;
pub mod reinforce;
pub mod symbols;
pub mod types;

use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

/// The commands this module owns.
pub const COMMANDS: &[&str] = &[
    "column",
    "structural_column",
    "footing",
    "beam",
    "strip_footing",
    "pipe",
    "duct",
    "conduit",
    "cable_tray",
    "wire",
    "down_conductor",
    "ground_conductor",
    "cabling",
    "rebar",
    "reinforce",
    "type",
    "family",
    "symbol_set",
    "component",
    "circuit",
    "conduit_fill",
    "drain_size",
    "vent_size",
    "hydrant_size",
    "load_points",
    "water_size",
    "storm_size",
];

pub fn owns(cid: &str) -> bool {
    COMMANDS.contains(&cid)
}

/// Runs the commands this module owns; None for the others.
pub fn dispatch(s: &mut Session, cid: &str, p: &Value) -> Option<Result<Value, String>> {
    if !owns(cid) {
        return None;
    }
    common::clear_step();
    Some(match cid {
        "column" | "structural_column" | "footing" | "beam" | "strip_footing" | "pipe" | "duct" | "conduit"
        | "cable_tray" | "wire" | "down_conductor" | "ground_conductor" | "cabling" => members::run(s, cid, p),
        "rebar" => rebar::run(s, cid, p),
        "reinforce" => reinforce::run(s, cid, p),
        "type" => types::run(s, cid, p),
        "family" => family::run(s, cid, p),
        "symbol_set" => symbols::run(s, cid, p),
        "component" => component::run(s, cid, p),
        _ => calc::run(s, cid, p),
    })
}

/// Whether the command just run makes an undo step though the model is as it was.
pub fn always_step(cid: &str) -> bool {
    owns(cid) && common::step_marked()
}

/// The model rules this module owns, checked after every command.
pub fn check(pr: &Project) -> Result<(), String> {
    types::check(pr)?;
    members::check(pr)?;
    family::check(pr)?;
    component::check(pr)?;
    rebar::check(pr)?;
    reinforce::check(pr)?;
    Ok(())
}

/// What `elements` shows of an element of this module's categories besides its fields (a run's
/// axis and length, its type's name and section; a component's connectors; a bar's length and
/// weight…), added to `x`, the element as the file holds it with its `id`.
pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
    let cat = x.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
    match cat.as_str() {
        "component" => component::element_view(pr, id, x),
        "rebar" => rebar::element_view(pr, id, x),
        c if common::is_run(c) || common::COLUMN_CATS.contains(&c) => members::element_view(pr, id, x),
        _ => {}
    }
}

/// What `inspect` warns of in this module's part of the model (a lighting, outlet or switch
/// family in use holding no connector…).
pub fn warnings(pr: &Project) -> Vec<String> {
    family::warnings(pr)
}
//! A session: the project, its file, and its undo history; commands run here.

use crate::json::Value;
use crate::project::Project;

pub struct Step {
    pub before: Project,
    pub after: Project,
    pub label: String,
}

pub struct Session {
    pub project: Project,
    pub path: Option<String>,
    pub undo: Vec<Step>,
    pub redo: Vec<Step>,
    pub read_only: bool,
    /// The phase and design option this session makes elements in.
    pub now_phase: Option<String>,
    pub now_option: Option<String>,
}

pub const MAX_UNDO: usize = 200;

impl Session {
    pub fn new() -> Session {
        Session {
            project: Project::new("en"),
            path: None,
            undo: Vec::new(),
            redo: Vec::new(),
            read_only: false,
            now_phase: None,
            now_option: None,
        }
    }

    /// Runs a command by id (or alias, any case) with its parameters.
    pub fn execute(&mut self, id: &str, params: &Value) -> Result<Value, String> {
        let Some((cid, label)) = crate::commands::resolve(id) else {
            return Err(format!("unknown command `{}`; list_commands shows them", id));
        };
        let before = self.project.clone();
        // the phase and option this session makes elements in go back with a refused command
        let now_before = (self.now_phase.clone(), self.now_option.clone());
        let res = crate::commands::run(self, &cid, params);
        match res {
            Ok(out) => {
                if crate::commands::changes_model(&cid) && !crate::commands::is_history_cmd(&cid) {
                    // a scan nothing places any more goes with the command that left it so
                    crate::cloud::drop_unplaced(&mut self.project);
                    if let Err(e) = crate::check::check(&self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if self.project.to_value() != before.to_value() || crate::commands::always_step(&cid) {
                        self.undo.push(Step { before, after: self.project.clone(), label: label.clone() });
                        if self.undo.len() > MAX_UNDO {
                            self.undo.remove(0);
                        }
                        self.redo.clear();
                    }
                }
                Ok(out)
            }
            Err(e) => {
                self.project = before;
                (self.now_phase, self.now_option) = now_before;
                Err(e)
            }
        }
    }

    pub fn history(&self) -> Vec<String> {
        self.undo.iter().map(|s| s.label.clone()).collect()
    }
}

//! Reading a command's parameters, with the errors the commands give.

use crate::json::Value;

pub type R<T> = Result<T, String>;

pub fn get<'a>(p: &'a Value, key: &str) -> Option<&'a Value> {
    match p.get(key) {
        Some(Value::Null) | None => None,
        Some(v) => Some(v),
    }
}

pub fn has(p: &Value, key: &str) -> bool {
    get(p, key).is_some()
}

/// Present in the object, even as null.
pub fn given(p: &Value, key: &str) -> bool {
    p.get(key).is_some()
}

pub fn num_of(v: &Value) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.as_f64()),
        _ => None,
    }
}

/// The largest length a command takes, in mm (1000 km).
pub const MAX_MM: f64 = 1e9;

/// A length in mm, within the model's reach.
pub fn mm_of(v: &Value) -> Option<f64> {
    let x = num_of(v)?;
    if x.is_finite() && x.abs() <= MAX_MM {
        Some(x)
    } else {
        None
    }
}

pub fn req_num(p: &Value, cmd: &str, key: &str) -> R<f64> {
    match get(p, key) {
        None => Err(format!("{}: `{}` in mm is required", cmd, key)),
        Some(v) => mm_of(v).ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_num(p: &Value, cmd: &str, key: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => mm_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A number in some unit other than mm (degrees, percent…).
pub fn opt_num_unit(p: &Value, cmd: &str, key: &str, unit: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => num_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number{}, got {}", cmd, key, unit, v.to_compact())),
    }
}

pub fn opt_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => Ok(Some(s.clone())),
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_bool(p: &Value, cmd: &str, key: &str) -> R<Option<bool>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(v) => Err(format!("{}: `{}` must be true or false, got {}", cmd, key, v.to_compact())),
    }
}

pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

pub fn point3_of(v: &Value) -> Option<[f64; 3]> {
    let a = v.as_arr()?;
    if a.len() != 3 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?, mm_of(&a[2])?])
}

pub fn req_point(p: &Value, cmd: &str, key: &str) -> R<[f64; 2]> {
    match get(p, key) {
        None => Err(format!("{}: `{}` [x, y] is required", cmd, key)),
        Some(v) => point_of(v).ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_point(p: &Value, cmd: &str, key: &str) -> R<Option<[f64; 2]>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => point_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A list of points; anything but a list of points reads as missing.
pub fn points_of(v: &Value) -> Option<Vec<[f64; 2]>> {
    let a = v.as_arr()?;
    a.iter().map(point_of).collect()
}

pub fn req_points(p: &Value, cmd: &str, key: &str) -> R<Vec<[f64; 2]>> {
    match get(p, key).and_then(points_of) {
        None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        Some(v) => Ok(v),
    }
}

pub fn opt_points(p: &Value, cmd: &str, key: &str) -> R<Option<Vec<[f64; 2]>>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => match points_of(v) {
            Some(pts) => Ok(Some(pts)),
            None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        },
    }
}

/// An element id: a number, or a GUID or an id in a string.
pub fn id_of(v: &Value) -> Option<u64> {
    match v {
        Value::Num(n) => {
            let f = n.as_f64();
            if f >= 0.0 && f.fract() == 0.0 {
                Some(f as u64)
            } else {
                None
            }
        }
        Value::Str(s) => s.trim().parse::<u64>().ok(),
        _ => None,
    }
}
//! What the style and settings commands share: reading their parameters with the errors the
//! original gives, colours and pens, and the library entries that name the project's styles.

use crate::json::{Map, Value};
use crate::project::Project;

pub type R<T> = Result<T, String>;

/// Refuses a parameter the command doesn't take: "`x` isn't one of its parameters: a, b, c", the
/// first such in sorted order (the original's parameters are a sorted map).
pub fn check_keys(p: &Value, cmd: &str, allowed: &[&str]) -> R<()> {
    if let Value::Obj(m) = p {
        let mut keys: Vec<&String> = m.items.iter().map(|(k, _)| k).collect();
        keys.sort();
        for k in keys {
            if !allowed.contains(&k.as_str()) {
                return Err(format!("{}: `{}` isn't one of its parameters: {}", cmd, k, allowed.join(", ")));
            }
        }
    }
    Ok(())
}

/// A text parameter, trimmed: None when absent, null or blank.
pub fn opt_name(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => {
            let t = s.trim();
            if t.is_empty() {
                Ok(None)
            } else {
                Ok(Some(t.to_string()))
            }
        }
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

/// `true` or `false` (null or absent: None).
pub fn opt_bool(p: &Value, cmd: &str, key: &str) -> R<Option<bool>> {
    crate::commands::params::opt_bool(p, cmd, key)
}

/// serde's "invalid type" message for a value that should have been of `expected` (f64, u8…).
pub fn invalid_type(v: &Value, expected: &str) -> String {
    format!("invalid type: {}, expected {}", v.kind_name(), expected)
}

/// A number as serde reads an f64 (any JSON number), else serde's error.
pub fn f64_of(v: &Value) -> Result<f64, String> {
    match v {
        Value::Num(n) => Ok(n.as_f64()),
        _ => Err(invalid_type(v, "f64")),
    }
}

/// A float as Rust's Display shows it (1.5, 17, 100000000000000000000).
pub fn disp(x: f64) -> String {
    format!("{}", x)
}

/// A pen: a whole number 0 (a hairline) to 16.
pub fn opt_pen(p: &Value, cmd: &str, key: &str) -> R<Option<u64>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(v) => {
            let x = f64_of(v).map_err(|e| format!("{}: `{}`: {}", cmd, key, e))?;
            pen_of(x).map(Some).ok_or_else(|| {
                format!(
                    "{}: `{}`: a line weight is a pen, a whole number from 0 (a hairline) to 16, not {}",
                    cmd,
                    key,
                    disp(x)
                )
            })
        }
    }
}

pub fn pen_of(x: f64) -> Option<u64> {
    if x.is_finite() && x.fract() == 0.0 && (0.0..=16.0).contains(&x) {
        Some(x as u64)
    } else {
        None
    }
}

/// A colour from "#rrggbb" or [r, g, b] (whole numbers 0 to 255).
pub fn color_of(v: &Value) -> Option<[u8; 3]> {
    match v {
        Value::Str(s) => {
            let h = s.strip_prefix('#')?;
            if h.len() != 6 || !h.chars().all(|c| c.is_ascii_hexdigit()) {
                return None;
            }
            let b = |i: usize| u8::from_str_radix(&h[i..i + 2], 16).ok();
            Some([b(0)?, b(2)?, b(4)?])
        }
        Value::Arr(a) if a.len() == 3 => {
            let mut out = [0u8; 3];
            for (i, x) in a.iter().enumerate() {
                match x {
                    Value::Num(crate::json::Num::U(u)) if *u <= 255 => out[i] = *u as u8,
                    _ => return None,
                }
            }
            Some(out)
        }
        _ => None,
    }
}

pub fn opt_color(p: &Value, cmd: &str, key: &str) -> R<Option<[u8; 3]>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(v) => color_of(v).map(Some).ok_or_else(|| {
            format!("{}: `{}` is \"#rrggbb\" or [r, g, b], each 0 to 255, not {}", cmd, key, v.to_compact())
        }),
    }
}

pub fn color_value(c: [u8; 3]) -> Value {
    Value::Arr(vec![Value::u(c[0] as u64), Value::u(c[1] as u64), Value::u(c[2] as u64)])
}

/// A colour as a file holds it ([r, g, b]); black when it holds none.
pub fn color_in(v: Option<&Value>) -> [u8; 3] {
    v.and_then(color_of).unwrap_or([0, 0, 0])
}

// ---------------------------------------------------------------- the library

/// The GUID of the library entry of this kind and name.
pub fn guid_of(pr: &Project, kind: &str, name: &str) -> Option<String> {
    pr.lib_guid(kind, name)
}

/// The name of the library entry of this kind with this GUID.
pub fn name_of_guid(pr: &Project, kind: &str, g: &str) -> Option<String> {
    pr.library
        .values()
        .find(|e| e.get("kind").and_then(|x| x.as_str()) == Some(kind) && e.get("guid").and_then(|x| x.as_str()) == Some(g))
        .and_then(|e| e.get("name"))
        .and_then(|n| n.as_str())
        .map(|s| s.to_string())
}

/// Renames the library entry of this kind and name.
pub fn lib_rename(pr: &mut Project, kind: &str, from: &str, to: &str) {
    if let Some(id) = pr.lib_find(kind, from) {
        if let Some(e) = pr.library.get_mut(&id) {
            e.set("name", Value::s(to));
        }
    }
}

/// Takes the library entry of this kind and name away.
pub fn lib_remove(pr: &mut Project, kind: &str, name: &str) {
    if let Some(id) = pr.lib_find(kind, name) {
        pr.library.remove(&id);
    }
}

/// The library entry of this kind and name, made if the project lacks it; its GUID.
pub fn lib_ensure(pr: &mut Project, kind: &str, name: &str) -> String {
    match pr.lib_guid(kind, name) {
        Some(g) => g,
        None => pr.lib_add(kind, name).1,
    }
}

/// How the model's check calls a library entry's kind ("line style", "design option set"); None
/// for the kinds it isn't known to hold to the rule below.
fn kind_words(kind: &str) -> Option<String> {
    if kind.starts_with("type:") || kind == "design-option" {
        return None;
    }
    Some(match kind {
        "option-set" => "design option set".to_string(),
        k => k.replace('-', " "),
    })
}

/// The model rule that no library entry is named like a GUID (a command takes a name or a GUID,
/// so one can't be the other): "line style `…`: a name isn't a GUID; name it otherwise", the
/// first such entry by id.
pub fn check_library_names(pr: &Project) -> R<()> {
    for e in pr.library.values() {
        let kind = e.get("kind").and_then(|k| k.as_str()).unwrap_or("");
        let Some(words) = kind_words(kind) else { continue };
        let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("");
        if super::electrical::as_guid(name).is_some() {
            return Err(format!("{} `{}`: a name isn't a GUID; name it otherwise", words, name));
        }
    }
    Ok(())
}

/// A section of the file as a map (empty if the project has none).
pub fn section(pr: &Project, key: &str) -> Map {
    pr.section(key).cloned().unwrap_or_default()
}

