import sys, json
sys.path.insert(0, '/tmp/elec-agent')
from lib import *
SECS = [0.5, 0.75, 1, 1.5, 2.5, 4, 6, 10, 16, 25, 35, 50, 70, 95, 120, 150, 185, 240, 300, 400, 500, 630, 800, 1000]
METHODS = ['1', '2', '3', '4', '5', '6', '7', '8', '11', '11A', '61', '61A']
cmds = []
keys = []
for ins in ['pvc', 'epr']:
    for m in METHODS:
        for ph in ['FF', '3F']:
            for s in SECS:
                cmds.append('circuit ' + json.dumps({"load": 1, "section": s, "method": m, "insulation": ins, "phases": ph}))
                keys.append((ins, m, ph, s))
r = batch(ORIG, cmds)
tab = {}
fac = {}
for k, x in zip(keys, r):
    if x.startswith('ERR'):
        tab[k] = x
        continue
    j = json.loads(x)
    tab[k] = j['chosen']['carries_a']
    fac[k[:3]] = j['factors']
for ins in ['pvc', 'epr']:
    print(ins)
    for m in METHODS:
        print(m, fac.get((ins, m, 'FF')), fac.get((ins, m, '3F')))
    for s in SECS:
        row = []
        for m in METHODS:
            for ph in ['FF', '3F']:
                row.append(str(tab[(ins, m, ph, s)]))
        print(s, ' '.join(row))

