    for b in [None, True]:
        for sp in sps:
            for g in gs:
                p = {"load": 1, "grouped": g, "method": m}
                if sp is not None:
                    p['spacing'] = sp
                if b is not None:
                    p['bundle'] = b
                cmds.append('circuit ' + json.dumps(p))
                keys.append((m, b, sp, g))
r = batch(ORIG, cmds)
cur = None
row = []
for k, x in zip(keys, r):
    y = x[4:] if x.startswith('ERR') else json.loads(x)['factors']['grouping']
    if k[:3] != cur:
        if row:
            print(cur, row)
        cur = k[:3]
        row = []
    row.append(y)
