def r2(x):
    y = x * 100.0
    f = math.floor(y)
    if y - f >= 0.5:
        f += 1
    return f / 100.0


VN = {'127/220': (127.0, 220.0), '220/380': (220.0, 380.0), '230/400': (230.0, 400.0)}


def r20(sec, flex, variant):
    i = SECS.index(sec)
    if flex:
        if i < len(R5):
            return R5[i]
        return R2[i] * 1.07
    return R2[i]


def rt(sec, flex, theta, variant):
    if variant == 'a':
        return r20(sec, flex, variant) * (1.0 + 0.00393 * (theta - 20.0))
    if variant == 'b':
        x = R2[SECS.index(sec)]
        if flex:
            i = SECS.index(sec)
            if i < len(R5):
                x = R5[i]
                return x * (1.0 + 0.00393 * (theta - 20.0))
            return x * (1.0 + 0.00393 * (theta - 20.0)) * 1.07
        return x * (1.0 + 0.00393 * (theta - 20.0))
    if variant == 'c':
        return r20(sec, flex, variant) * (1.0 + 0.00393 * (theta - 20.0))


def drop_variants():
    def mk(name, f):
        return name, f
    yield mk('k*I*L*(Rc+Xs)/V*100', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm / 1e6) * (R * c + 0.1 * s) / V * 100.0)
    yield mk('k*I*L*(Rc+Xs)*100/V', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm / 1e6) * (R * c + 0.1 * s) * 100.0 / V)
    yield mk('100*k*I*L*(Rc+Xs)/V', lambda k, I, Lmm, R, c, s, V: 100.0 * k * I * (Lmm / 1e6) * (R * c + 0.1 * s) / V)
    yield mk('(k*I*L*(Rc+Xs))/V*100 Lm', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm / 1000.0) * (R * c + 0.1 * s) / 1000.0 / V * 100.0)
    yield mk('k*I*(Lmm/1000)*(Rc+Xs)/1000/V*100', lambda k, I, Lmm, R, c, s, V: k * I * ((Lmm / 1000.0) / 1000.0) * (R * c + 0.1 * s) / V * 100.0)
    yield mk('k*(Rc+Xs)*I*L/V*100', lambda k, I, Lmm, R, c, s, V: k * (R * c + 0.1 * s) * I * (Lmm / 1e6) / V * 100.0)
    yield mk('k*L*I*(Rc+Xs)/V*100', lambda k, I, Lmm, R, c, s, V: k * (Lmm / 1e6) * I * (R * c + 0.1 * s) / V * 100.0)
    yield mk('dv=k*I*L*(..); dv/V*100', lambda k, I, Lmm, R, c, s, V: (k * I * (Lmm / 1e6) * (R * c + 0.1 * s)) / V * 100.0)
    yield mk('k*I*((Rc+Xs)*L)/V*100', lambda k, I, Lmm, R, c, s, V: k * I * ((R * c + 0.1 * s) * (Lmm / 1e6)) / V * 100.0)
    yield mk('k*I*(Rc*L+Xs*L)/V*100', lambda k, I, Lmm, R, c, s, V: k * I * (R * c * (Lmm / 1e6) + 0.1 * s * (Lmm / 1e6)) / V * 100.0)
    yield mk('k*I*L/1000*(Rc+Xs)/V*100 [L m]', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm / 1000.0) / 1000.0 * (R * c + 0.1 * s) / V * 100.0)
    yield mk('k*I*Lm*(Rc+Xs)/1000/V*100', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm / 1000.0) * (R * c + 0.1 * s) / 1000.0 / V * 100.0)
    yield mk('k*I*Lm*((Rc+Xs)/1000)/V*100', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm / 1000.0) * ((R * c + 0.1 * s) / 1000.0) / V * 100.0)
    yield mk('k*I*Lkm*(Rc+Xs)/V*100 Lkm=Lmm*1e-6', lambda k, I, Lmm, R, c, s, V: k * I * (Lmm * 1e-6) * (R * c + 0.1 * s) / V * 100.0)


for var in ['a', 'b']:
    for sinv in ['sqrt(1-c2)', 'sin(acos)']:
        for name, f in drop_variants():
            bad = 0
            ex = None
            for p, cur, drop, volts in samples:
                three = p['phases'] in ('3F', '3FN')
                V = VN[p['system']][0 if p['phases'] == 'FN' else 1]
                d = p.get('demand', 1.0)
                pf = p.get('power_factor', 1.0)
                pfi = 1.0 if p.get('apparent') else pf
                va = p['load'] * d / pfi
                I = va / ((S3 if three else 1.0) * V)
                k = S3 if three else 2.0
                c = pf
                s = math.sqrt(1.0 - c * c) if sinv == 'sqrt(1-c2)' else math.sin(math.acos(c))
                theta = 70.0 if p['insulation'] == 'pvc' else 90.0
                R = rt(p['section'], p['conductor'] == 'flexible', theta, var)
                v = r2(f(k, I, p['length'], R, c, s, V))
                if v != drop:
                    bad += 1
                    ex = (p, drop, v)
            print(var, sinv, name, bad, len(samples), ex if bad < 30 else '')

