import subprocess, json, sys
exe = sys.argv[1] if len(sys.argv) > 1 else '/workspace/executable'
p = subprocess.Popen([exe, 'mcp'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd='/tmp/elec-agent')
def send(o):
    p.stdin.write((json.dumps(o) + '\n').encode())
    p.stdin.flush()
    line = p.stdout.readline()
    return json.loads(line)
r = send({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "t", "version": "1"}}})
