    if prm is not None:
        a["params"] = prm
    r = send({"jsonrpc": "2.0", "id": 10 + i, "method": "tools/call", "params": {"name": "execute", "arguments": a}})
    print(json.dumps(r, ensure_ascii=False)[:600])

