"""Edge cases of `circuit`: every key with every kind of wrong value, the boundaries, the order of checks."""
import sys, json, random, itertools
sys.path.insert(0, '/tmp/elec-agent')
from mlib import *

KEYS = ["load", "apparent", "demand", "power_factor", "phases", "system", "use", "length", "method", "insulation",
        "conductor", "ambient", "grouped", "bundle", "spacing", "soil", "section", "breaker", "drop_limit", "reduced_neutral"]
VALS = [None, "x", "", "FN", "7", "11A", "pvc", True, False, [], [1], {}, {"a": 1}, -1, -0.5, 0, -0.0, 0.5, 1, 1.0, 2, 2.5,
        3, 4, 7, 10, 11, 20, 61, 100, 1000, 1000.5, 1e5, 1e9, 1e10, 1e300, 1e-300, 2.2250738585072014e-308,
        18446744073709551615, -9223372036854775808, "x" * 3000, ["y" * 2500]]
calls = []
for k in KEYS:
    for v in VALS:
        p = {"load": 1000} if k != 'load' else {}
        p[k] = v
        calls.append(('circuit', p))
        p2 = dict(p)
        p2['length'] = p2.get('length', 25000) if k != 'length' else v
        p2['section'] = 2.5 if k != 'section' else v
        calls.append(('circuit', p2))
# pairs of bad keys: order of checks
bad = {"load": "x", "apparent": "x", "demand": "x", "power_factor": "x", "phases": "x", "system": "x", "use": "x",
       "length": "x", "method": "x", "insulation": "x", "conductor": "x", "ambient": "x", "grouped": "x", "bundle": "x",
       "spacing": "x", "soil": "x", "section": "x", "breaker": "x", "drop_limit": "x", "reduced_neutral": "x"}
for a, b in itertools.combinations(KEYS, 2):
    calls.append(('circuit', {"load": 1000, a: bad[a], b: bad[b]}))
    calls.append(('circuit', {a: bad[a], b: bad[b]}))
# semantic errors against parse errors
sem = [{"ambient": 5}, {"ambient": 65}, {"ambient": 85, "insulation": "epr"}, {"method": "61", "grouped": 7},
       {"method": "61A", "grouped": 3, "spacing": 2000}, {"method": "61", "soil": 0.5}, {"method": "61", "soil": 4},
       {"load": 1e9}, {"section": 3}, {"breaker": 11}, {"unknown": 1}]
for x, y in itertools.permutations(sem, 2):
    p = {"load": 1000}
    p.update(x)
    p.update(y)
    calls.append(('circuit', p))
for k in KEYS:
    for x in sem:
        p = {"load": 1000}
        p.update(x)
        p[k] = "x"
        calls.append(('circuit', p))
# not an object
for v in [None, [], [1], 1, "x", True]:
    calls.append(('circuit', v))
# boundaries
for L in [0, 1e-9, 0.5, 1, 1000, 1e6, 1e7, 1e8, 5e8, 1e9]:
    for load in [1, 100, 1000, 10000, 100000, 126999, 127000, 127000.0000001, 1e6]:
        calls.append(('circuit', {"load": load, "length": L}))
        calls.append(('circuit', {"load": load, "length": L, "drop_limit": 100}))
        calls.append(('circuit', {"load": load, "length": L, "phases": "3FN", "system": "230/400", "drop_limit": 0.1}))
for amb in [9.999, 10, 10.000000001, 12.5, 30, 59.99, 60, 60.0000000005, 60.000001, 61, 75, 80, 80.0000000005, 80.1, 199]:
    for ins in ['pvc', 'epr']:
        for m in ['7', '61']:
            calls.append(('circuit', {"load": 1000, "ambient": amb, "insulation": ins, "method": m}))
for g in [1, 1.49, 1.5, 2, 5.5, 6, 6.49, 6.5, 8.5, 11.49, 11.5, 15.5, 19.49, 19.5, 999.5, 1000]:
    for m in ['7', '11', '11A', '61', '61A']:
        for b in [False, True]:
            for sp in [0, 249.999999, 250, 500, 999.9999, 1000, 1000.000001, 1000.00001, 100000]:
                calls.append(('circuit', {"load": 1000, "grouped": g, "method": m, "bundle": b, "spacing": sp}))
print(len(calls))
mcompare(calls, label='circuit edges: ')

