import json, math, itertools
from collections import defaultdict
out = json.load(open('/tmp/elec-agent/cf_ties_orig.json'))
SECS = [0.5, 0.75, 1, 1.5, 2.5, 4, 6, 10, 16, 25, 35, 50, 70, 95, 120, 150, 185, 240]
DIA = [2.15, 2.35, 2.5, 2.95, 3.55, 4.05, 4.65, 6.0, 7.0, 8.6, 10.15, 11.8, 13.5, 15.7, 17.2, 19.1, 21.4, 24.2]
dia = dict(zip(SECS, DIA))
exec(open('/tmp/elec-agent/cf12.py').read().split('NEU =')[1].split('ties = []')[0].replace(' {35:', 'NEU = {35:', 1)) if False else None
NEU = {35: 25, 50: 25, 70: 35, 95: 50, 120: 70, 150: 70, 185: 95, 240: 120}
INS = {}
for line in open('/tmp/elec-agent/cf12.py'):
    pass
src = open('/tmp/elec-agent/cf12.py').read()
INS = eval(src.split('INS = ')[1].split('\nNEU')[0])


def pe(s):
    if s <= 16: return s
    if s <= 35: return 16
    return min(x for x in SECS if x >= s / 2)


def conds(s, ph, red):
    n = s if not (red and ph == '3FN') else NEU.get(s, s)
    return {'FN': [s, s, pe(s)], 'FF': [s, s, pe(s)], '3F': [s, s, s, pe(s)], '3FN': [s, s, s, n, pe(s)]}[ph]


pi = math.pi


def rr(x):
    y = x * 10.0
    f = math.floor(y)
    if y - f >= 0.5:
        f += 1
    return f / 10.0


def sum_(vals):
    s = 0.0
    for v in vals:
        s += v
    return s


areas = {
    'x*x': lambda x: x * x,
    'pi*x*x/4': lambda x: pi * x * x / 4.0,
    'pi/4*x*x': lambda x: pi / 4.0 * x * x,
    'pi*((x/2)*(x/2))': lambda x: pi * ((x / 2.0) * (x / 2.0)),
    'pi*(x/2)*(x/2)': lambda x: pi * (x / 2.0) * (x / 2.0),
    '(x/2)*(x/2)*pi': lambda x: (x / 2.0) * (x / 2.0) * pi,
    'x*x*pi/4': lambda x: x * x * pi / 4.0,
    'pi*(x*x)/4': lambda x: pi * (x * x) / 4.0,
    'pi*(x*x/4)': lambda x: pi * (x * x / 4.0),
    'x*x/4*pi': lambda x: x * x / 4.0 * pi,
    'pi*x*x*0.25': lambda x: pi * x * x * 0.25,
}
sums = {
    'n*sum': lambda vals, n: n * sum_(vals),
    'sum*n': lambda vals, n: sum_(vals) * n,
    'expanded': lambda vals, n: sum_(vals * n),
    'expanded-percond': lambda vals, n: sum_([v for v in vals for _ in range(n)]),
    'sum(v*n)': lambda vals, n: sum_([v * n for v in vals]),
}
pcts = {
    'a/b*100': lambda a, b: a / b * 100.0,
    'a*100/b': lambda a, b: a * 100.0 / b,
    '100*a/b': lambda a, b: 100.0 * a / b,
}
byc = defaultdict(list)
for o in out:
    byc[(o[0], o[1])].append(o)


def cand(D):
    x = float(D)
    c = {0: x}
    y = x
    for k in range(1, 5):
        y = math.nextafter(y, math.inf)
        c[k] = y
    y = x
    for k in range(1, 5):
        y = math.nextafter(y, -math.inf)
        c[-k] = y
    return c


res = []
for (an, af), (sn, sf), (pn, pf) in itertools.product(areas.items(), sums.items(), pcts.items()):
    total = 0
    choice = {}
    for key, cases in byc.items():
        best = None
        for k, D in cand(INS[key]).items():
            good = 0
            for o in cases:
                fam, size, s, ph, red, n, ex, fill, ok, sm = o
                vals = [af(dia[x]) for x in conds(s, ph, red)]
                v = rr(pf(sf(vals, n), af(D)))
                if v == fill:
                    good += 1
            if best is None or good > best[0]:
                best = (good, k)
        total += best[0]
        choice[key] = best
    res.append((total, an, sn, pn, choice))
res.sort(key=lambda r: -r[0])
for r in res[:8]:
    print(r[0], len(out), r[1], r[2], r[3])
    print('   ', {k: v for k, v in r[4].items()})

