usage: sweep_conduit.py [N] [seed]"""
import sys, json, random, itertools
sys.path.insert(0, '/tmp/elec-agent')
from mlib import *

N = int(sys.argv[1]) if len(sys.argv) > 1 else 5000
seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
random.seed(seed)
FAM = {'pvc-thread': ['1/2"', '3/4"', '1"', '1.1/4"', '1.1/2"', '2"', '2.1/2"', '3"', '4"'],
       'pvc-solder': ['DN20', 'DN25', 'DN32'],
       'steel-heavy': ['1/2"', '3/4"', '1"', '1.1/4"', '1.1/2"', '2"', '2.1/2"', '3"', '4"'],
       'steel-rir': ['1/2"', '3/4"', '1"', '1.1/4"', '1.1/2"', '2"', '2.1/2"', '3"', '4"', '5"', '6"']}
SECS = [0.5, 0.75, 1, 1.5, 2.5, 4, 6, 10, 16, 25, 35, 50, 70, 95, 120, 150, 185, 240, 300, 400, 500, 630, 800, 1000]
JUNK = [None, "x", True, False, [1], {"a": 1}, -1, 0, 1e300, -0.0, 2.5, 1e-9, "", 1000000, 1.5, 3, "1\"", "DN20"]


def gen():
    p = {}
    r = random.random
    p['section'] = random.choice(SECS + [random.choice(SECS) + random.choice([1e-10, -1e-10, 1e-8, 0.5])] if r() < 0.1 else SECS)
    f = None
    if r() < 0.7:
        f = random.choice(list(FAM))
        p['family'] = f
    if r() < 0.6:
        p['size'] = random.choice(FAM[f or 'pvc-thread'] + (['DN20', '5"', 'x'] if r() < 0.1 else []))
    if r() < 0.6:
        p['phases'] = random.choice(['FN', 'FF', '3F', '3FN'])
    if r() < 0.6:
        p['circuits'] = random.choice([1, 2, 3, 4, 5, 6, random.randint(1, 20), random.randint(1, 1000), round(random.uniform(1, 10), 1)])
    if r() < 0.3:
        p['reduced_neutral'] = random.choice([True, False])
    if r() < 0.12:
        k = random.choice(list(p.keys()) + ['section', 'size', 'family', 'foo'])
        p[k] = random.choice(JUNK)
    return p


calls = [('conduit_fill', gen()) for _ in range(N)]
mcompare(calls, label='conduit_fill random seed %d: ' % seed)

# tie cases (exact decimal halves) and the 40 % boundary
ties = json.load(open('/tmp/elec-agent/cf_ties_orig.json'))
calls = []
for t in ties:
    fam, size, s, ph, red, n = t[:6]
    p = {"section": s, "family": fam, "size": size, "phases": ph, "circuits": n}
    if red:
        p['reduced_neutral'] = True
    calls.append(('conduit_fill', p))
mcompare(calls, label='conduit_fill ties: ')

