        1e9, 1e300, 1e-300, 18446744073709551615, "x" * 300, "x" * 3000, "FN", "3FN", "pvc-solder", '1"', 'DN25', '6"']
for k in KEYS + ['foo', 'Section']:
    for v in VALS:
        p = {"section": 2.5} if k != 'section' else {}
        p[k] = v
        calls.append(('conduit_fill', p))
        p2 = dict(p)
        if k != 'section':
            p2['section'] = 300
        calls.append(('conduit_fill', p2))
bad = {"section": "x", "phases": "x", "circuits": "x", "reduced_neutral": "x", "family": "x", "size": 5, "foo": 1}
for a, b in itertools.combinations(bad, 2):
    calls.append(('conduit_fill', {a: bad[a], b: bad[b]}))
    calls.append(('conduit_fill', {"section": 2.5, a: bad[a], b: bad[b]}))
    calls.append(('conduit_fill', {"section": 300, a: bad[a], b: bad[b]}))
for v in [None, [], [1], 1, "x", True]:
    calls.append(('conduit_fill', v))
for s in SECS + [0.6, 17, 36, 241, 2.5000000001, 2.500000001, 35.0000000001, 50.0000000001, 16.0000000001]:
    for ph in ['FN', 'FF', '3F', '3FN']:
        for red in [False, True]:
            for f in FAM:
                calls.append(('conduit_fill', {"section": s, "phases": ph, "reduced_neutral": red, "family": f}))
                calls.append(('conduit_fill', {"section": s, "phases": ph, "reduced_neutral": red, "family": f, "size": FAM[f][-1], "circuits": 7}))
mcompare(calls, label='conduit_fill edges: ')

