//! Rooms: number, name, level, and a point the imported walls enclose.

use super::build::mm;
use super::bytes::*;
use super::cats;
use super::data;
use super::import::Ctx;
use super::notes::Kind;
use super::plan;
use crate::json::Value;

const NUMBER: i64 = -1006901;
const NAME: i64 = -1006900;
pub const NOT_ENCLOSED: &str =
    "the walls imported do not enclose its box (curtain walls and room separation lines are not imported)";

/// The room's number and name, from its object in the newest partition that has one.
fn params(ctx: &Ctx, id: u64) -> (Option<String>, Option<String>) {
    let doc = ctx.doc;
    let wide = doc.wide();
    let mut key = vec![1u8, 0, 0, 0];
    if wide {
        key.extend_from_slice(&id.to_le_bytes());
    } else {
        key.extend_from_slice(&(id as u32).to_le_bytes());
    }
    for pi in doc.parts_newest_first() {
        let d = &doc.parts[pi].data;
        let mut last = None;
        let mut q = 0;
        while let Some(p) = find(d, &key, q, d.len()) {
            last = Some(p);
            q = p + 1;
        }
        let p = match last {
            Some(p) => p,
            None => continue,
        };
        let end = (p + 0x400).min(d.len());
        let entry = |pid: i64| -> Option<String> {
            let k: Vec<u8> = if wide { pid.to_le_bytes().to_vec() } else { (pid as i32).to_le_bytes().to_vec() };
            let m = find(d, &k, p, end)?;
            let (s, _) = data::counted(d, m + k.len(), 1000)?;
            Some(s)
        };
        return (entry(NUMBER), entry(NAME));
    }
    (None, None)
}

pub fn read(ctx: &mut Ctx) {
    let kind = Kind::simple("room");
    // the walls that came in, as lines in plan, by level
    // the walls that came in, as lines in plan, with the heights they span (mm)
    let elev = |g: &str| -> f64 {
        ctx.levels.iter().find(|l| l.guid.as_deref() == Some(g)).map(|l| l.elevation).unwrap_or(0.0)
    };
    let mut segs: Vec<((f64, f64), plan::P, plan::P)> = Vec::new();
    for e in ctx.pr.elements.values() {
        if e.get("category").and_then(|c| c.as_str()) != Some("wall") {
            continue;
        }
        let num = |k: &str| e.get(k).and_then(|x| x.as_f64()).unwrap_or(0.0);
        let base = elev(e.get("level").and_then(|l| l.as_str()).unwrap_or("")) + num("base_offset");
        let lv = (base, base + num("height"));
        let s = e.get("start").and_then(crate::commands::params::point_of);
        let t = e.get("end").and_then(crate::commands::params::point_of);
        let (s, t) = match (s, t) {
            (Some(s), Some(t)) => (s, t),
            _ => continue,
        };
        match e.get("arc").and_then(|a| a.as_f64()) {
            Some(sweep) if sweep != 0.0 => {
                // the arc through both ends with this sweep (degrees, counter-clockwise when positive)
                let sw = sweep.to_radians();
                let chord = ((t[0] - s[0]).powi(2) + (t[1] - s[1]).powi(2)).sqrt();
                let r = chord / 2.0 / (sw.abs() / 2.0).sin();
                let mid = [(s[0] + t[0]) / 2.0, (s[1] + t[1]) / 2.0];
                let d = (r * r - (chord / 2.0).powi(2)).max(0.0).sqrt();
                let n = [-(t[1] - s[1]) / chord, (t[0] - s[0]) / chord];

                let n = [-(t[1] - s[1]) / chord, (t[0] - s[0]) / chord];
                let sign = if (sw > 0.0) == (sw.abs() < std::f64::consts::PI) { 1.0 } else { -1.0 };
                let c = [mid[0] + sign * d * n[0], mid[1] + sign * d * n[1]];
                let a0 = (s[1] - c[1]).atan2(s[0] - c[0]);
                let pts = plan::arc_points(c, r, a0, sw);
                for w in pts.windows(2) {
                    segs.push((lv, w[0], w[1]));
                }
            }
            _ => segs.push((lv, s, t)),
        }
    }
    for r in ctx.instances(cats::OST_ROOMS) {
        let b = match r.bbox {
            Some(b) => b,
            None => continue,
        };
        let level = match ctx.base_level(&r.refs, b[2]) {
            Some(l) => l,
            None => {
                ctx.notes.leave(&kind, super::walls::NO_LEVEL, r.id);
                continue;
            }
        };
        // the walls the level's plan cuts, 1200 mm over it, whatever level they stand on
        let cut = ctx.levels[level].elevation + 1200.0;
        let lsegs: Vec<(plan::P, plan::P)> = segs.iter().filter(|s| s.0 .0 <= cut && cut < s.0 .1).map(|s| (s.1, s.2)).collect();
        let faces = plan::faces(&lsegs);
        let (x0, y0, x1, y1) = (mm(b[0]), mm(b[1]), mm(b[3]), mm(b[4]));
        let (w, h) = (x1 - x0, y1 - y0);
        // the box's centre first, then the centres of a 9 by 9 grid over it, nearest first
        let c = [(x0 + x1) / 2.0, (y0 + y1) / 2.0];
        let mut cands: Vec<(f64, plan::P)> = vec![(-1.0, c)];
        for iy in 0..9 {
            for ix in 0..9 {
                let p = [x0 + (ix as f64 + 0.5) * w / 9.0, y0 + (iy as f64 + 0.5) * h / 9.0];
                let d = (p[0] - c[0]) * (p[0] - c[0]) + (p[1] - c[1]) * (p[1] - c[1]);
                cands.push((d, p));
            }
        }
        cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
        let tol = 1e-6;
        let mut point = None;
        for (_, p) in cands {
            if let Some(f) = faces.around(p) {
                let fx0 = f.iter().map(|q| q[0]).fold(f64::INFINITY, f64::min);
                let fy0 = f.iter().map(|q| q[1]).fold(f64::INFINITY, f64::min);
                let fx1 = f.iter().map(|q| q[0]).fold(f64::NEG_INFINITY, f64::max);
                let fy1 = f.iter().map(|q| q[1]).fold(f64::NEG_INFINITY, f64::max);
                if fx0 <= x0 + tol && fy0 <= y0 + tol && fx1 >= x1 - tol && fy1 >= y1 - tol {
                    point = Some(p);
                    break;
                }
            }
        }
        let point = match point {
            Some(p) => p,
            None => {
                ctx.notes.leave(&kind, NOT_ENCLOSED, r.id);
                continue;
            }
        };
        let (number, name) = params(ctx, r.id);
        let v = jobj! {
            "guid" => crate::rand::guid(),
            "category" => "room",
            "level" => ctx.level_guid(level),
            "point" => Value::Arr(vec![Value::f(point[0]), Value::f(point[1])]),
            "name" => name.unwrap_or_else(|| "Room".to_string()),
            "number" => number.unwrap_or_default(),
        };
        ctx.add(r.id, "room", v);
    }
}
//! Plan geometry the import needs: the faces the walls' lines make in plan (to tell whether
//! walls enclose a point, as BIMCraft's rooms find their boundaries), and arcs as chords.

const EPS: f64 = 1e-6;

pub type P = [f64; 2];

fn cross(o: P, a: P, b: P) -> f64 {
    (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
}

/// Where two segments meet (as parameters along the first), if they do.
fn meet(a0: P, a1: P, b0: P, b1: P) -> Vec<f64> {
    let d = [a1[0] - a0[0], a1[1] - a0[1]];
    let e = [b1[0] - b0[0], b1[1] - b0[1]];
    let den = d[0] * e[1] - d[1] * e[0];
    let len2 = d[0] * d[0] + d[1] * d[1];
    if len2 < EPS * EPS {
        return vec![];
    }
    let mut out = Vec::new();
    if den.abs() < 1e-12 {
        // parallel: collinear overlap gives the other's ends that lie on this one
        if cross(a0, a1, b0).abs() / len2.sqrt() > 1e-6 {
            return vec![];
        }
        for q in [b0, b1] {
            let t = ((q[0] - a0[0]) * d[0] + (q[1] - a0[1]) * d[1]) / len2;
            if t > -1e-9 && t < 1.0 + 1e-9 {
                out.push(t.clamp(0.0, 1.0));
            }
        }
        return out;
    }
    let w = [b0[0] - a0[0], b0[1] - a0[1]];
    let t = (w[0] * e[1] - w[1] * e[0]) / den;
    let u = (w[0] * d[1] - w[1] * d[0]) / den;
    let tl = 1e-9;
    if t > -tl && t < 1.0 + tl && u > -tl && u < 1.0 + tl {
        out.push(t.clamp(0.0, 1.0));
    }
    out
}

pub struct Faces {
    /// Each bounded face's outer boundary, counter-clockwise.
    pub faces: Vec<Vec<P>>,
}

fn key(p: P) -> (i64, i64) {
    ((p[0] * 1000.0).round() as i64, (p[1] * 1000.0).round() as i64)
}

/// The bounded faces the segments make in plan.
pub fn faces(segs: &[(P, P)]) -> Faces {
    // split every segment where another meets it
    let mut pieces: Vec<(P, P)> = Vec::new();
    for (i, s) in segs.iter().enumerate() {
        let mut ts = vec![0.0, 1.0];
        for (j, o) in segs.iter().enumerate() {
            if i != j {
                ts.extend(meet(s.0, s.1, o.0, o.1));
            }
        }
        ts.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let pt = |t: f64| [s.0[0] + t * (s.1[0] - s.0[0]), s.0[1] + t * (s.1[1] - s.0[1])];
        for w in ts.windows(2) {
            let (a, b) = (pt(w[0]), pt(w[1]));
            if key(a) != key(b) {
                pieces.push((a, b));
            }
        }
    }
    // vertices and undirected edges
    let mut verts: Vec<P> = Vec::new();
    let mut vid: std::collections::HashMap<(i64, i64), usize> = std::collections::HashMap::new();
    let mut edges: std::collections::BTreeSet<(usize, usize)> = std::collections::BTreeSet::new();
    for (a, b) in pieces {
        let ia = *vid.entry(key(a)).or_insert_with(|| {
            verts.push(a);
            verts.len() - 1
        });
        let ib = *vid.entry(key(b)).or_insert_with(|| {
            verts.push(b);
            verts.len() - 1
        });
        if ia != ib {
            edges.insert((ia.min(ib), ia.max(ib)));
        }
    }
    // half-edges, each vertex's outgoing ones sorted by angle
    let mut out: Vec<Vec<usize>> = vec![Vec::new(); verts.len()];
    for &(a, b) in &edges {
        out[a].push(b);
        out[b].push(a);
    }
    let ang = |a: usize, b: usize| (verts[b][1] - verts[a][1]).atan2(verts[b][0] - verts[a][0]);
    for (a, o) in out.iter_mut().enumerate() {
        o.sort_by(|x, y| ang(a, *x).partial_cmp(&ang(a, *y)).unwrap());
    }
    let mut used: std::collections::HashSet<(usize, usize)> = std::collections::HashSet::new();
    let mut faces = Vec::new();
    for a in 0..verts.len() {
        for &b in &out[a] {
            if used.contains(&(a, b)) {
                continue;
            }
            // walk: at each vertex take the next edge clockwise from the one we came in by
            let mut cyc = vec![a];
            let (mut u, mut v) = (a, b);
            let mut steps = 0;
            loop {
                used.insert((u, v));
                let o = &out[v];
                let k = o.iter().position(|x| *x == u).unwrap();
                let w = o[(k + o.len() - 1) % o.len()];
                u = v;
                v = w;
                if u == a && v == b {
                    break;
                }
                cyc.push(u);
                steps += 1;
                if steps > 4 * edges.len() + 4 {
                    break;
                }
            }
            let pts: Vec<P> = cyc.iter().map(|i| verts[*i]).collect();
            if area(&pts) > EPS {
                faces.push(pts);
            }
        }
    }
    Faces { faces }
}

pub fn area(p: &[P]) -> f64 {
    let mut s = 0.0;
    for i in 0..p.len() {
        let (a, b) = (p[i], p[(i + 1) % p.len()]);
        s += a[0] * b[1] - b[0] * a[1];
    }
    s / 2.0
}

/// Whether the point is inside the polygon, not on its edge.
pub fn inside(poly: &[P], q: P) -> bool {
    let n = poly.len();
    for i in 0..n {
        let (a, b) = (poly[i], poly[(i + 1) % n]);
        let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
        if len > 0.0 && cross(a, b, q).abs() / len < 1e-6 {
            let t = ((q[0] - a[0]) * (b[0] - a[0]) + (q[1] - a[1]) * (b[1] - a[1])) / (len * len);
            if t >= -1e-9 && t <= 1.0 + 1e-9 {
                return false;
            }
        }
    }
    let mut c = false;
    for i in 0..n {
        let (a, b) = (poly[i], poly[(i + 1) % n]);
        if (a[1] > q[1]) != (b[1] > q[1]) {
            let x = a[0] + (q[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1]);
            if q[0] < x {
                c = !c;
            }
        }
    }
    c
}

impl Faces {
    /// The smallest face the point is inside.
    pub fn around(&self, q: P) -> Option<&Vec<P>> {
        let mut best: Option<(&Vec<P>, f64)> = None;
        for f in &self.faces {
            if inside(f, q) {
                let a = area(f);
                if best.map(|(_, ba)| a < ba).unwrap_or(true) {
                    best = Some((f, a));
                }
            }
        }
        best.map(|(f, _)| f)
    }
}

/// Points along an arc in plan, as chords within half a millimetre of it.
pub fn arc_points(centre: P, radius: f64, a0: f64, sweep: f64) -> Vec<P> {
    let tol = 0.5f64;
    let n = if radius > tol {
        let step = 2.0 * (1.0 - tol / radius).acos();
        ((sweep.abs() / step).ceil() as usize).max(1)
    } else {
        1
    };
    (0..=n)
        .map(|k| {
            let a = a0 + sweep * k as f64 / n as f64;
            [centre[0] + radius * a.cos(), centre[1] + radius * a.sin()]
        })
        .collect()
}

