import math
obs = {  # (R, sweep): (centre area m2, finish area m2, finish perimeter m)
    (500, 90): (0.2, 0.12, 1.4), (500, 45): (0.1, 0.04, 0.91),
    (1000, 90): (0.78, 0.62, 3.19), (1000, 45): (0.39, 0.27, 2.3),
    (3000, 90): (7.07, 6.54, 10.33), (3000, 45): (3.53, 3.13, 7.88),
    (10000, 90): (78.53, 76.75, 35.33), (10000, 45): (39.26, 37.88, 27.37),
    (30000, 90): (706.83, 701.48, 106.74), (30000, 45): (353.41, 349.25, 83.08),
    (100000, 90): (7853.88, 7836.03, 356.7), (100000, 45): (3926.94, 3913.02, 278.06),
}


def clip(poly, a, b, c):
    # keep a*x + b*y >= c
    out = []
    n = len(poly)
    for i in range(n):
        p, q = poly[i], poly[(i + 1) % n]
        fp = a * p[0] + b * p[1] - c
        fq = a * q[0] + b * q[1] - c
        if fp >= 0:
            out.append(p)
        if (fp >= 0) != (fq >= 0):
            t = fp / (fp - fq)
            out.append((p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])))
    return out


def area(p):
    return sum(p[i][0] * p[(i + 1) % len(p)][1] - p[(i + 1) % len(p)][0] * p[i][1] for i in range(len(p))) / 2


def perim(p):
    return sum(math.dist(p[i], p[(i + 1) % len(p)]) for i in range(len(p)))


def nseg(r, sweep, scheme):
    if scheme[0] == 'tol':
        tol = scheme[1]
        if r <= tol:
            return 1
        step = 2 * math.acos(1 - tol / r)
        return max(1, math.ceil(abs(sweep) / step))
    if scheme[0] == 'deg':
        return max(1, math.ceil(math.degrees(abs(sweep)) / scheme[1]))


def model(R, deg, scheme, per_face):
    sw = math.radians(deg)
    t = 100.0
    n_c = nseg(R, sw, scheme)
    # centre area: sector polygon
    pts = [(0.0, 0.0)] + [(R * math.cos(sw * k / n_c), R * math.sin(sw * k / n_c)) for k in range(n_c + 1)]
    ca = area(pts) / 1e6
    ri = R - t / 2
    n_i = nseg(ri, sw, scheme) if per_face else n_c
    inner = [(0.0, 0.0)] + [(ri * math.cos(sw * k / n_i), ri * math.sin(sw * k / n_i)) for k in range(n_i + 1)]
    # the two straight walls' faces: y >= 50 and the other wall along angle sw: distance >= 50 on the inside
    poly = clip(inner, 0, 1, t / 2)
    # second wall from (R cos sw, R sin sw) to (0,0): inside is to the right when walking from end to centre...
    nx, ny = math.sin(sw), -math.cos(sw)  # unit normal pointing into the sector from the line at angle sw
    poly = clip(poly, nx, ny, t / 2)
    return ca, area(poly) / 1e6, perim(poly) / 1e3


for scheme in [('tol', 0.5), ('tol', 1.0), ('tol', 2.0), ('deg', 0.5), ('deg', 1), ('deg', 3), ('deg', 5)]:
    for per_face in [False, True]:
        bad = 0
        for (R, deg), (c, fa, fp) in obs.items():
            mc, ma, mp = model(R, deg, scheme, per_face)
            if round(mc, 2) != c or round(ma, 2) != fa or round(mp, 2) != fp:
                bad += 1
        print(scheme, per_face, 'mismatches', bad, 'of', len(obs))
for (R, deg), v in obs.items():
    print(R, deg, v, [round(x, 4) for x in model(R, deg, ('tol', 1.0), True)], [round(x, 4) for x in model(R, deg, ('tol', 1.0), False)])

