//! A room's kind as its name says it, in Portuguese or English: the name lower-cased, its accents
//! taken off, then searched for the words of each kind, a service area's first, then a
//! bathroom's, a kitchen's, a veranda's and a dry room's.

/// The name as the words are looked for in it: lower case, without accents.
pub fn fold(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for c in name.chars() {
        for l in c.to_lowercase() {
            out.push(match l {
                'á' | 'à' | 'â' | 'ã' | 'ä' => 'a',
                'é' | 'è' | 'ê' | 'ë' => 'e',
                'í' | 'ì' | 'î' | 'ï' => 'i',
                'ó' | 'ò' | 'ô' | 'õ' | 'ö' => 'o',
                'ú' | 'ù' | 'û' | 'ü' => 'u',
                'ç' => 'c',
                x => x,
            });
        }
    }
    out
}

/// Each kind with the words found anywhere in a name and the words that must stand alone.
const KINDS: &[(&str, &[&str], &[&str])] = &[
    ("service", &["servico", "lavanderia", "laundry", "utility"], &[]),
    ("bath", &["banheiro", "lavabo", "sanitario", "toilet", "bathroom", "restroom"], &["wc", "bwc", "bath"]),
    ("kitchen", &["cozinha", "copa", "kitchen", "pantry"], &[]),
    ("veranda", &["varanda", "sacada", "balcony", "veranda"], &[]),
    ("dry", &["sala", "quarto", "dormitorio", "suite", "bedroom", "living"], &[]),
];

/// The kind a name says, if it says one.
pub fn kind_of(name: &str) -> Option<&'static str> {
    let f = fold(name);
    let words: Vec<&str> = f.split(|c: char| !c.is_alphanumeric()).filter(|w| !w.is_empty()).collect();
    for (kind, parts, whole) in KINDS {
        if parts.iter().any(|p| f.contains(p)) || words.iter().any(|w| whole.contains(w)) {
            return Some(kind);
        }
    }
    None
}

/// Whether a name says a kitchen or a pantry, which has the outlets over the sink's counter.
pub fn has_counter(name: &str) -> bool {
    let f = fold(name);
    ["cozinha", "copa", "kitchen"].iter().any(|p| f.contains(p))
}

//! `load_points`: NBR 5410:2004 item 9.5.2: a dwelling's lighting and general-use outlets.
//!
//! Each room has a ceiling lighting point of 100 VA up to 6 m², 60 VA more for each whole 4 m²
//! above; and general-use outlets (TUG) by its kind: a bathroom 1, a kitchen (pantry) or service
//! area (laundry) one for each 3.5 m of perimeter, a room or bedroom one for each 5 m, a veranda 1,
//! the others 1 up to 6 m² and one for each 5 m above; 600 VA each for the first 3 in a
//! bathroom, kitchen or service area (the first 2 by the alternative, where those rooms have more
//! than 6 points together) and 100 VA for the others. The rooms are given, or the model's,
//! measured inside the walls' finish.

mod kinds;
mod rooms;

use super::circuit::args::{clip, flag, given, num};
use crate::json::{Map, Value};
use crate::session::Session;
use crate::structure::common::R;

const NOT_COVERED: &str = "the exceptions to the lighting point and to a veranda's outlet, the placement of the outlets (near the lavatory, over a counter, up to 0.80 m outside the door of a room of 2.25 m² or less) and the TUE";
const KINDS: &[&str] = &["bath", "kitchen", "service", "dry", "veranda", "other"];
const ROOM_KEYS: &[&str] = &["area", "kind", "name", "perimeter", "points"];

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    points(s, cid, p).map_err(clip)
}

/// A room as the rules read it: its name, kind (and whether the name gave it), area (m²),
/// perimeter (m) and the outlets it has.
struct Room {
    name: String,
    kind: &'static str,
    named: bool,
    area: f64,
    perimeter: f64,
    points: Option<u64>,
}

fn points(s: &mut Session, cmd: &str, p: &Value) -> R<Value> {
    let m = p.as_obj().ok_or_else(|| format!("{}: params must be an object", cmd))?;
    let mut keys: Vec<&String> = m.keys().collect();
    keys.sort();
    for k in keys {
        if k != "rooms" && k != "alternative" {
            return Err(format!("{}: `{}` isn't one of its parameters: rooms, alternative", cmd, k));
        }
    }
    let alternative = flag(cmd, m, "alternative")?.unwrap_or(false);
    let mut list = Vec::new();
    let mut skipped = Vec::new();
    match given(m, "rooms") {
        None => {
            let (found, left) = rooms::model_rooms(&s.project);
            for (name, area, perimeter) in found {
                list.push(room_of(name, None, area, perimeter, None));
            }
            skipped = left;
        }
        Some(v) => {
            let arr = match v {
                Value::Arr(a) if a.len() <= 5000 => a,
                _ => {
                    return Err(format!(
                        "{}: `rooms` must be a list of at most 5000 rooms, got {}",
                        cmd,
                        v.to_compact()
                    ))
                }
            };
            for (i, r) in arr.iter().enumerate() {
                list.push(read_room(cmd, i, r)?);
            }
        }
    }
    Ok(report(list, skipped, alternative))
}

/// One room of `rooms`, read with the original's texts and in its order.
fn read_room(cmd: &str, i: usize, r: &Value) -> R<Room> {
    let m = r.as_obj().ok_or_else(|| format!("{}: rooms[{}] must be an object", cmd, i))?;
    let mut keys: Vec<&String> = m.keys().collect();
    keys.sort();
    for k in keys {
        if !ROOM_KEYS.contains(&k.as_str()) {
            return Err(format!("{}: rooms[{}]: unknown parameter `{}`", cmd, i, k));
        }
    }
    let at = |e: String| format!("rooms[{}]: {}", i, e);
    let name = match given(m, "name") {
        None => String::new(),
        Some(Value::Str(s)) if s.chars().count() <= 256 => s.clone(),
        Some(v) => {
            return Err(at(format!(
                "{}: `name` must be text of at most 256 characters, got {}",
                cmd,
                v.to_compact()
            )))
        }
    };
    let area = num(cmd, m, "area", 0.0, 1e6).map_err(at)?;
    let perimeter = num(cmd, m, "perimeter", 0.0, 1e9).map_err(at)?;
    let (Some(area), Some(perimeter)) = (area, perimeter) else {
        return Err(format!("{}: rooms[{}]: `area` (m²) and `perimeter` (mm) are required", cmd, i));
    };
    let kind = match given(m, "kind") {
        None => None,
        Some(v) => match v.as_str().and_then(|s| KINDS.iter().find(|k| **k == s)) {
            Some(k) => Some(*k),
            None => {
                return Err(at(format!(
                    "{}: `kind` must be one of {}, got {}",
                    cmd,
                    KINDS.join(", "),
                    v.to_compact()
                )))
            }
        },
    };
    let points = match given(m, "points") {
        None => None,
        Some(Value::Num(crate::json::Num::U(n))) if *n <= 1000 => Some(*n),
        Some(v) => {
            return Err(format!(
                "{}: rooms[{}]: `points` must be a whole number from 0 to 1000, got {}",
                cmd,
                i,
                v.to_compact()
            ))
        }
    };
    Ok(room_of(name, kind, area, perimeter / 1000.0, points))
}

fn room_of(name: String, kind: Option<&'static str>, area: f64, perimeter: f64, points: Option<u64>) -> Room {
    let (kind, named) = match kind {
        Some(k) => (k, true),
        None => match kinds::kind_of(&name) {
            Some(k) => (k, true),
            None => ("other", false),
        },
    };
    Room { name, kind, named, area, perimeter, points }
}

fn wet(kind: &str) -> bool {
    matches!(kind, "bath" | "kitchen" | "service")
}

/// The outlets a room needs at least.
fn minimum(r: &Room) -> u64 {
    let by = |step: f64| ((r.perimeter / step - 1e-9).ceil().max(1.0)) as u64;
    match r.kind {
        "bath" | "veranda" => 1,
        "kitchen" | "service" => by(3.5),
        "dry" => by(5.0),
        _ => {
            if r.area <= 6.0 {
                1
            } else {
                by(5.0)
            }
        }
    }
}

fn lighting(area: f64) -> f64 {
    if area <= 6.0 {
        100.0
    } else {
        100.0 + 60.0 * ((area - 6.0) / 4.0 + 1e-9).floor()
    }
}

fn report(list: Vec<Room>, skipped: Vec<Value>, alternative: bool) -> Value {
    let mins: Vec<u64> = list.iter().map(minimum).collect();
    let pts: Vec<u64> = list.iter().zip(&mins).map(|(r, m)| r.points.unwrap_or(*m)).collect();
    let wet_points: u64 = list.iter().zip(&pts).filter(|(r, _)| wet(r.kind)).map(|(_, p)| *p).sum();
    let possible = wet_points > 6;
    let applied = alternative && possible;
    let first = if applied { 2 } else { 3 };
    let mut rooms = Vec::new();
    let mut light_sum = -0.0;
    let mut tug_sum = -0.0;
    let mut all_ok = true;
    for ((r, m), p) in list.iter().zip(&mins).zip(&pts) {
        let light = lighting(r.area);
        let tug = if wet(r.kind) {
            let k = (*p).min(first);
            600.0 * k as f64 + 100.0 * (*p - k) as f64
        } else {
            100.0 * *p as f64
        };
        let ok = p >= m;
        all_ok &= ok;
        light_sum += light;
        tug_sum += tug;
        let mut o = Map::new();
        o.insert("area_m2", Value::f((r.area * 100.0).round() / 100.0));
        if r.kind == "kitchen" && kinds::has_counter(&r.name) {
            o.insert("counter_outlets", Value::u(2));
        }
        o.insert("kind", Value::s(r.kind));
        o.insert("lighting_points", Value::u(1));
        o.insert("lighting_va", Value::f(light));
        o.insert("name", Value::s(&r.name));
        if !r.named {
            o.insert("note", Value::s("the name says no kind of room: treated as `other`; give `kind`"));
        }
        o.insert("ok", Value::Bool(ok));
        o.insert("perimeter_m", Value::f((r.perimeter * 100.0).round() / 100.0));
        o.insert("tug_minimum", Value::u(*m));
        o.insert("tug_points", Value::u(*p));
        o.insert("tug_va", Value::f(tug));
        rooms.push(Value::Obj(o));
    }
    let mut out = Map::new();
    out.insert("alternative_applied", Value::Bool(applied));
    out.insert("alternative_possible", Value::Bool(possible));
    out.insert("lighting_va", Value::f(light_sum));
    out.insert("not_covered", Value::s(NOT_COVERED));
    out.insert("ok", Value::Bool(all_ok));
    out.insert("rooms", Value::Arr(rooms));
    out.insert("skipped", Value::Arr(skipped));
    out.insert("total_va", Value::f(light_sum + tug_sum));
    out.insert("tug_va", Value::f(tug_sum));
    out.insert("wet_points", Value::u(wet_points));
    Value::Obj(out)
}

//! The model's rooms as `load_points` measures them, inside the walls' finish: a private stand-in
//! for the architecture part's room boundaries, read from the project as the file holds it.
//!
//! A room's level is cut at its `computation_height` (1200 mm over it): the walls the cut passes
//! through (their base at or under it, their top over it) that bound rooms, and the room
//! separation lines of the level, bound it. Each wall is its plan footprint (its faces each side
//! of its location line, by its type's thickness and core); two walls meeting end to end are
//! mitred, and a wall ending within another's thickness (and a millimetre) of its centre line is
//! carried to it. The room is the free face of those outlines around its point, less the walls
//! standing free inside it; a face another room (one of a lower id) has is not its, and a room
//! where nothing encloses its point is skipped. A frozen room keeps the boundary it was frozen
//! with.

use crate::json::{Map, Value};
use crate::project::Project;
use std::collections::{BTreeMap, HashMap};

type P = [f64; 2];

const WHY: &str = "not enclosed by walls";

fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
fn crs(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
fn len(a: P) -> f64 {
    (a[0] * a[0] + a[1] * a[1]).sqrt()
}
fn dist(a: P, b: P) -> f64 {
    len(sub(a, b))
}

fn point(v: Option<&Value>) -> Option<P> {
    let a = v?.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?])
}

fn num(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

/// The model's rooms in id order: (name, area m², perimeter m) of those measured, and the
/// skipped ones as `{id, name, why}`.
pub fn model_rooms(pr: &Project) -> (Vec<(String, f64, f64)>, Vec<Value>) {
    let model = Model::read(pr);
    let mut found = Vec::new();
    let mut skipped = Vec::new();
    let mut plans: HashMap<String, Plan> = HashMap::new();
    for (id, e) in &pr.elements {
        if e.get("category").and_then(|c| c.as_str()) != Some("room") {
            continue;
        }
        let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
        let skip = |skipped: &mut Vec<Value>| {
            let mut o = Map::new();
            o.insert("id", Value::u(*id));
            o.insert("name", Value::s(&name));
            o.insert("why", Value::s(WHY));
            skipped.push(Value::Obj(o));
        };
        if e.get("frozen").and_then(|f| f.as_bool()) == Some(true) {
            if let Some(k) = e.get("kept").and_then(|k| k.get("finish")) {
                if let Some((a, p)) = kept_measure(k) {
                    found.push((name, a / 1e6, p / 1000.0));
                    continue;
                }
            }
        }
        let level = e.get("level").and_then(|l| l.as_str()).unwrap_or("").to_string();
        let Some(q) = point(e.get("point")) else {
            skip(&mut skipped);
            continue;
        };
        if !model.levels.contains_key(&level) {
            skip(&mut skipped);
            continue;
        }
        let plan = plans.entry(level.clone()).or_insert_with(|| Plan::of_level(&model, &level));
        match plan.room_at(q) {
            Some((a, p)) => found.push((name, a / 1e6, p / 1000.0)),
            None => skip(&mut skipped),
        }
    }
    (found, skipped)
}

/// The area (mm²) and perimeter (mm) of a kept boundary `{outer, holes}`.
fn kept_measure(k: &Value) -> Option<(f64, f64)> {
    let ring = |v: &Value| -> Option<Vec<P>> { v.as_arr()?.iter().map(|p| point(Some(p))).collect() };
    let outer = ring(k.get("outer")?)?;
    let mut a = area(&outer).abs();
    let mut p = perimeter(&outer);
    if let Some(hs) = k.get("holes").and_then(|h| h.as_arr()) {
        for h in hs {
            let h = ring(h)?;
            a -= area(&h).abs();
            p += perimeter(&h);
        }
    }
    Some((a, p))
}

fn area(p: &[P]) -> f64 {
    let mut s = 0.0;
    for i in 0..p.len() {
        let (a, b) = (p[i], p[(i + 1) % p.len()]);
        s += a[0] * b[1] - b[0] * a[1];
    }
    s / 2.0
}

fn perimeter(p: &[P]) -> f64 {
    (0..p.len()).map(|i| dist(p[i], p[(i + 1) % p.len()])).sum()
}

/// Whether the point is inside the polygon (an even-odd ray to +x).
fn inside(poly: &[P], q: P) -> bool {
    let n = poly.len();
    let mut c = false;
    for i in 0..n {
        let (a, b) = (poly[i], poly[(i + 1) % n]);
        if (a[1] > q[1]) != (b[1] > q[1]) {
            let x = a[0] + (q[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1]);
            if q[0] < x {
                c = !c;
            }
        }
    }
    c
}

// ---------------------------------------------------------------- the model as rooms see it

struct WallType {
    thickness: f64,
    core: (f64, f64),
}

struct Wall {
    level: String,
    base: f64,
    top: f64,
    bounding: bool,
    start: P,
    end: P,
    arc: f64,
    /// The exterior face's distance to the left of the location line, and the thickness.
    left: f64,
    thickness: f64,
}

struct Model {
    /// Level GUID → (elevation, computation height).
    levels: HashMap<String, (f64, f64)>,
    walls: Vec<Wall>,
    /// Room separation lines by level.
    separators: Vec<(String, P, P)>,
}

impl Model {
    fn read(pr: &Project) -> Model {
        let mut levels = HashMap::new();
        for e in pr.elements.values() {
            if e.get("category").and_then(|c| c.as_str()) == Some("level") {
                if let Some(g) = e.get("guid").and_then(|g| g.as_str()) {
                    let elev = num(e, "elevation").unwrap_or(0.0);
                    let ch = num(e, "computation_height").unwrap_or(1200.0);
                    levels.insert(g.to_string(), (elev, ch));
                }
            }
        }
        // the wall types by their library GUID
        let mut types: HashMap<String, WallType> = HashMap::new();
        let defs = pr.section("types").and_then(|t| t.get("wall")).and_then(|w| w.as_obj());
        for entry in pr.library.values() {
            if entry.get("kind").and_then(|k| k.as_str()) != Some("type:wall") {
                continue;
            }
            let (Some(g), Some(n)) = (entry.get("guid").and_then(|g| g.as_str()), entry.get("name").and_then(|n| n.as_str()))
            else {
                continue;
            };
            if let Some(t) = defs.and_then(|d| d.get(n)) {
                types.insert(g.to_string(), wall_type(t));
            }
        }
        let mut walls = Vec::new();
        let mut separators = Vec::new();
        for e in pr.elements.values() {
            match e.get("category").and_then(|c| c.as_str()) {
                Some("wall") => {
                    let (Some(s), Some(t)) = (point(e.get("start")), point(e.get("end"))) else { continue };
                    let level = e.get("level").and_then(|l| l.as_str()).unwrap_or("").to_string();
                    let elev = levels.get(&level).map(|l| l.0).unwrap_or(0.0);
                    let base = elev + num(e, "base_offset").unwrap_or(0.0);
                    let top = match e.get("top_level").and_then(|l| l.as_str()).and_then(|g| levels.get(g)) {
                        Some(l) => l.0 + num(e, "top_offset").unwrap_or(0.0),
                        None => base + num(e, "height").unwrap_or(0.0),
                    };
                    let wt = e.get("type").and_then(|g| g.as_str()).and_then(|g| types.get(g));
                    let thickness = wt.map(|w| w.thickness).unwrap_or(200.0);
                    let core = wt.map(|w| w.core).unwrap_or((0.0, thickness));
                    let left = match e.get("location").and_then(|l| l.as_str()).unwrap_or("centre") {
                        "exterior-finish" => 0.0,
                        "interior-finish" => thickness,
                        "core-centre" => (core.0 + core.1) / 2.0,
                        "exterior-core" => core.0,
                        "interior-core" => core.1,
                        _ => thickness / 2.0,
                    };
                    walls.push(Wall {
                        level,
                        base,
                        top,
                        bounding: e.get("room_bounding").and_then(|b| b.as_bool()) != Some(false),
                        start: s,
                        end: t,
