/// A wall type's thickness and its core (from its exterior face, from its first structure layer
/// to its last; all of it where it has none).
fn wall_type(t: &Value) -> WallType {
    let layers: Vec<(String, f64)> = t
        .get("layers")
        .and_then(|l| l.as_arr())
        .map(|ls| {
            ls.iter()
                .map(|l| {
                    (
                        l.get("function").and_then(|f| f.as_str()).unwrap_or("").to_string(),
                        l.get("thickness").and_then(|x| x.as_f64()).unwrap_or(0.0),
                    )
                })
                .collect()
        })
        .unwrap_or_default();
    let sum: f64 = layers.iter().map(|l| l.1).sum();
    let thickness = t.get("thickness").and_then(|x| x.as_f64()).unwrap_or(if layers.is_empty() { 200.0 } else { sum });
    let mut core = (0.0, thickness);
    let first = layers.iter().position(|l| l.0 == "structure");
    let last = layers.iter().rposition(|l| l.0 == "structure");
    if let (Some(f), Some(l)) = (first, last) {
        let a: f64 = layers[..f].iter().map(|x| x.1).sum();
        let b: f64 = layers[..=l].iter().map(|x| x.1).sum();
        core = (a, b);
    }
    WallType { thickness, core }
}

// ---------------------------------------------------------------- footprints

/// A wall's footprint: its left face and right face as polylines from its start to its end.
struct Outline {
    left: Vec<P>,
    right: Vec<P>,
    /// The centre line, for the T joins.
    centre: Vec<P>,
    half: f64,
}

/// The arc through both ends turning `sweep` degrees counter-clockwise: centre, radius, start
/// angle, sweep in radians.
fn arc_of(s: P, t: P, sweep: f64) -> Option<(P, f64, f64, f64)> {
    let sw = sweep.to_radians();
    let chord = dist(s, t);
    if chord < 1e-9 || sw.abs() < 1e-12 {
        return None;
    }
    let r = chord / 2.0 / (sw.abs() / 2.0).sin();
    let mid = mul(add(s, t), 0.5);
    let d = (r * r - (chord / 2.0).powi(2)).max(0.0).sqrt();
    let n = [-(t[1] - s[1]) / chord, (t[0] - s[0]) / chord];
    let sign = if (sw > 0.0) == (sw.abs() < std::f64::consts::PI) { 1.0 } else { -1.0 };
    let c = add(mid, mul(n, sign * d));
    let a0 = (s[1] - c[1]).atan2(s[0] - c[0]);
    Some((c, r, a0, sw))
}

fn outline(w: &Wall) -> Option<Outline> {
    let lo = w.left;
    let ro = w.thickness - w.left;
    let mid = (lo - ro) / 2.0; // the centre line's offset to the left of the location line
    if let Some((c, r, a0, sw)) = arc_of(w.start, w.end, w.arc) {
        let tol = 1.0f64;
        let n = if r > tol { ((sw.abs() / (2.0 * (1.0 - tol / r).acos())).ceil() as usize).max(1) } else { 1 };
        // to the left of a counter-clockwise arc is its centre
        let ccw = sw > 0.0;
        let ring = |off: f64| -> Vec<P> {
            let rr = if ccw { r - off } else { r + off };
            (0..=n)
                .map(|k| {
                    let a = a0 + sw * k as f64 / n as f64;
                    [c[0] + rr * a.cos(), c[1] + rr * a.sin()]
                })
                .collect()
        };
        return Some(Outline { left: ring(lo), right: ring(-ro), centre: ring(mid), half: w.thickness / 2.0 });
    }
    let d = sub(w.end, w.start);
    let l = len(d);
    if l < 1e-6 {
        return None;
    }
    let u = mul(d, 1.0 / l);
    let nl = [-u[1], u[0]];
    let off = |k: f64| vec![add(w.start, mul(nl, k)), add(w.end, mul(nl, k))];
    Some(Outline { left: off(lo), right: off(-ro), centre: off(mid), half: w.thickness / 2.0 })
}

/// Where two lines (a point and a direction each) cross.
fn cross_lines(p: P, u: P, q: P, v: P) -> Option<P> {
    let den = crs(u, v);
    if den.abs() < 1e-12 * len(u) * len(v) {
        return None;
    }
    let t = crs(sub(q, p), v) / den;
    Some(add(p, mul(u, t)))
}

/// A face polyline's line at one of its ends: (the end point, the direction away from the wall).
fn end_line(face: &[P], at_start: bool) -> (P, P) {
    if at_start {
        (face[0], sub(face[0], face[1]))
    } else {
        let n = face.len();
        (face[n - 1], sub(face[n - 1], face[n - 2]))
    }
}

/// The walls' outlines with their joins: ends meeting end to end are mitred, an end within a
/// wall's thickness of its centre line is carried to it.
fn joined(walls: &[&Wall]) -> Vec<Outline> {
    let mut outs: Vec<Option<Outline>> = walls.iter().map(|w| outline(w)).collect();
    let ends: Vec<(usize, bool, P)> = (0..walls.len())
        .filter(|i| outs[*i].is_some())
        .flat_map(|i| [(i, true, walls[i].start), (i, false, walls[i].end)])
        .collect();
    // T joins: an end that meets no other end, within a wall's band of its centre line, goes to it
    let mut moved: Vec<(usize, bool, P)> = Vec::new();
    for &(i, at_start, p) in &ends {
        let meets = ends.iter().any(|&(j, _, q)| j != i && dist(p, q) <= 1.0);
        if meets {
            continue;
        }
        for (j, o) in outs.iter().enumerate() {
            let Some(o) = o else { continue };
            if j == i {
                continue;
            }
            let c = &o.centre;
            for k in 0..c.len() - 1 {
                let (a, b) = (c[k], c[k + 1]);
                let ab = sub(b, a);
                let l2 = dot(ab, ab);
                if l2 < 1e-12 {
                    continue;
                }
                let t = dot(sub(p, a), ab) / l2;
                let first = k == 0;
                let last = k == c.len() - 2;
                if (first && t <= 1e-9) || (last && t >= 1.0 - 1e-9) || t < 0.0 || t > 1.0 {
                    continue;
                }
                let f = add(a, mul(ab, t));
                if dist(p, f) <= o.half + 1.0 && dist(p, f) > 1e-9 {
                    moved.push((i, at_start, f));
                }
            }
        }
    }
    for (i, at_start, f) in moved {
        if walls[i].arc != 0.0 {
            continue;
        }
        let w = walls[i];
        let (s, e) = if at_start { (f, w.end) } else { (w.start, f) };
        let nw = Wall {
            level: String::new(),
            base: 0.0,
            top: 0.0,
            bounding: true,
            start: s,
            end: e,
            arc: 0.0,
            left: w.left,
            thickness: w.thickness,
        };
        if let Some(o) = outline(&nw) {
            // keep the other end as it is
            if let Some(old) = &outs[i] {
                let mut o = o;
                if at_start {
                    *o.left.last_mut().unwrap() = *old.left.last().unwrap();
                    *o.right.last_mut().unwrap() = *old.right.last().unwrap();
                } else {
                    o.left[0] = old.left[0];
                    o.right[0] = old.right[0];
                }
                outs[i] = Some(o);
            }
        }
    }
    // L joins: two ends meeting, and only two, are mitred
    for a in 0..ends.len() {
        let (i, ia, p) = ends[a];
        let others: Vec<usize> = (0..ends.len()).filter(|&b| b != a && ends[b].0 != i && dist(ends[b].2, p) <= 1.0).collect();
        if others.len() != 1 {
            continue;
        }
        let b = others[0];
        if b < a {
            continue;
        }
        let (j, jb, _) = ends[b];
        let (Some(oi), Some(oj)) = (&outs[i], &outs[j]) else { continue };
        // each face seen going away from the joint: to the left of the way out of a wall's start is
        // its left face, out of its end its right face
        let (il, ir) = if ia { (&oi.left, &oi.right) } else { (&oi.right, &oi.left) };
        let (jl, jr) = if jb { (&oj.left, &oj.right) } else { (&oj.right, &oj.left) };
        let (p1, u1) = end_line(il, ia);
        let (q1, v1) = end_line(jr, jb);
        let (p2, u2) = end_line(ir, ia);
        let (q2, v2) = end_line(jl, jb);
        let (Some(m1), Some(m2)) = (cross_lines(p1, u1, q1, v1), cross_lines(p2, u2, q2, v2)) else { continue };
        // a mitre that runs far off (walls almost in line) is left out
        let reach = 10.0 * (oi.half + oj.half).max(1.0);
        if dist(m1, p) > reach || dist(m2, p) > reach {
            continue;
        }
        let set = |o: &mut Outline, at_start: bool, leftward: P, rightward: P| {
            let (l, r) = if at_start { (&mut o.left, &mut o.right) } else { (&mut o.right, &mut o.left) };
            let li = if at_start { 0 } else { l.len() - 1 };
            let ri = if at_start { 0 } else { r.len() - 1 };
            l[li] = leftward;
            r[ri] = rightward;
        };
        if let Some(o) = &mut outs[i] {
            set(o, ia, m1, m2);
        }
        if let Some(o) = &mut outs[j] {
            set(o, jb, m2, m1);
        }
    }
    outs.into_iter().flatten().collect()
}

fn polygon(o: &Outline) -> Vec<P> {
    let mut p = o.left.clone();
    p.extend(o.right.iter().rev());
    p
}

// ---------------------------------------------------------------- the plan's faces

struct Plan {
    walls: Vec<Vec<P>>,
    verts: Vec<P>,
    /// Each cycle of half-edges: its vertices, signed area and the component it belongs to.
    cycles: Vec<(Vec<usize>, f64, usize)>,
    taken: Vec<usize>,
}

impl Plan {
    fn of_level(m: &Model, level: &str) -> Plan {
        let (elev, ch) = m.levels.get(level).copied().unwrap_or((0.0, 1200.0));
        let cut = elev + ch;
        let walls: Vec<&Wall> = m.walls.iter().filter(|w| w.bounding && w.base <= cut && cut < w.top).collect();
        let outlines = joined(&walls);
        let polys: Vec<Vec<P>> = outlines.iter().map(polygon).collect();
        let mut segs: Vec<(P, P)> = Vec::new();
        for p in &polys {
            for k in 0..p.len() {
                segs.push((p[k], p[(k + 1) % p.len()]));
            }
        }
        for (l, s, t) in &m.separators {
            if l == level {
                segs.push((*s, *t));
            }
        }
        let (verts, cycles) = faces(&segs);
        Plan { walls: polys, verts, cycles, taken: Vec::new() }
    }

    fn ring(&self, c: usize) -> Vec<P> {
        self.cycles[c].0.iter().map(|i| self.verts[*i]).collect()
    }

    /// The room around a point: its area (mm²) and perimeter (mm), if it is enclosed and no room
    /// has its face already.
    fn room_at(&mut self, q: P) -> Option<(f64, f64)> {
        if self.walls.iter().any(|w| inside(w, q)) {
            return None;
        }
        let mut best: Option<(usize, f64)> = None;
        for (c, (_, a, _)) in self.cycles.iter().enumerate() {
            if *a <= 1e-6 {
                continue;
            }
            if inside(&self.ring(c), q) && best.map(|(_, ba)| *a < ba).unwrap_or(true) {
                best = Some((c, *a));
            }
        }
        let (f, fa) = best?;
        if self.taken.contains(&f) {
            return None;
        }
        self.taken.push(f);
        let outer = self.ring(f);
        let comp = self.cycles[f].2;
        let mut a = fa;
        let mut p = perimeter(&outer);
        for (h, (vs, ha, hc)) in self.cycles.iter().enumerate() {
            if *ha >= -1e-6 || *hc == comp {
                continue;
            }
            let v = self.verts[vs[0]];
            if !inside(&outer, v) {
                continue;
            }
            // the face holding the hole directly: the smallest of the other components' faces round it
            let mut holder: Option<(usize, f64)> = None;
            for (c, (_, ca, cc)) in self.cycles.iter().enumerate() {
                if *ca <= 1e-6 || *cc == *hc {
                    continue;
                }
                if inside(&self.ring(c), v) && holder.map(|(_, ba)| *ca < ba).unwrap_or(true) {
                    holder = Some((c, *ca));
                }
            }
            if holder.map(|(c, _)| c) != Some(f) {
                continue;
            }
            let ring = self.ring(h);
            a -= ha.abs();
            p += perimeter(&ring);
        }
        Some((a, p))
    }
}

fn key(p: P) -> (i64, i64) {
    ((p[0] * 1e4).round() as i64, (p[1] * 1e4).round() as i64)
}

/// Where segment b meets segment a, as parameters along a.
fn meet(a0: P, a1: P, b0: P, b1: P) -> Vec<f64> {
    let d = sub(a1, a0);
    let e = sub(b1, b0);
    let l2 = dot(d, d);
    if l2 < 1e-12 {
        return vec![];
    }
    let den = crs(d, e);
    let mut out = Vec::new();
    if den.abs() < 1e-9 * l2.sqrt() * len(e).max(1e-12) {
        // parallel: the other's ends on this one
        if crs(d, sub(b0, a0)).abs() / l2.sqrt() > 1e-6 {
            return out;
        }
        for q in [b0, b1] {
            let t = dot(sub(q, a0), d) / l2;
            if t > -1e-9 && t < 1.0 + 1e-9 {
                out.push(t.clamp(0.0, 1.0));
            }
        }
        return out;
    }
    let w = sub(b0, a0);
    let t = crs(w, e) / den;
    let u = crs(w, d) / den;
    let tl = 1e-9;
    if t > -tl && t < 1.0 + tl && u > -tl && u < 1.0 + tl {
        out.push(t.clamp(0.0, 1.0));
    }
    out
}

/// The cycles the segments make: each with its vertices, signed area and connected component.
fn faces(segs: &[(P, P)]) -> (Vec<P>, Vec<(Vec<usize>, f64, usize)>) {
    let mut pieces: Vec<(P, P)> = Vec::new();
    for (i, s) in segs.iter().enumerate() {
        let mut ts = vec![0.0, 1.0];
        for (j, o) in segs.iter().enumerate() {
            if i != j {
                ts.extend(meet(s.0, s.1, o.0, o.1));
            }
        }
        ts.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let pt = |t: f64| add(s.0, mul(sub(s.1, s.0), t));
        for w in ts.windows(2) {
            let (a, b) = (pt(w[0]), pt(w[1]));
            if key(a) != key(b) {
                pieces.push((a, b));
            }
        }
    }
    let mut verts: Vec<P> = Vec::new();
    let mut vid: HashMap<(i64, i64), usize> = HashMap::new();
    let mut edges: std::collections::BTreeSet<(usize, usize)> = std::collections::BTreeSet::new();
    for (a, b) in pieces {
        let ia = *vid.entry(key(a)).or_insert_with(|| {
            verts.push(a);
            verts.len() - 1
        });
        let ib = *vid.entry(key(b)).or_insert_with(|| {
            verts.push(b);
            verts.len() - 1
        });
        if ia != ib {
            edges.insert((ia.min(ib), ia.max(ib)));
        }
    }
    // connected components
    let mut parent: Vec<usize> = (0..verts.len()).collect();
    fn root(p: &mut Vec<usize>, x: usize) -> usize {
        let mut r = x;
        while p[r] != r {
            r = p[r];
        }
        let mut y = x;
        while p[y] != r {
            let n = p[y];
            p[y] = r;
            y = n;
        }
        r
    }
    for &(a, b) in &edges {
        let (ra, rb) = (root(&mut parent, a), root(&mut parent, b));
        if ra != rb {
            parent[ra] = rb;
        }
    }
    let mut out: Vec<Vec<usize>> = vec![Vec::new(); verts.len()];
    for &(a, b) in &edges {
        out[a].push(b);
        out[b].push(a);
    }
    let ang = |a: usize, b: usize| (verts[b][1] - verts[a][1]).atan2(verts[b][0] - verts[a][0]);
    for (a, o) in out.iter_mut().enumerate() {
        o.sort_by(|x, y| ang(a, *x).partial_cmp(&ang(a, *y)).unwrap_or(std::cmp::Ordering::Equal));
    }
    let mut used: std::collections::HashSet<(usize, usize)> = std::collections::HashSet::new();
    let mut cycles = Vec::new();
    let mut by_start: BTreeMap<usize, ()> = BTreeMap::new();
    for a in 0..verts.len() {
        for &b in &out[a] {
            if used.contains(&(a, b)) {
                continue;
            }
            let mut cyc = vec![a];
            let (mut u, mut v) = (a, b);
            let mut steps = 0;
            loop {
                used.insert((u, v));
                let o = &out[v];
                let k = o.iter().position(|x| *x == u).unwrap_or(0);
                let w = o[(k + o.len() - 1) % o.len()];
                u = v;
                v = w;
                if u == a && v == b {
                    break;
                }
                cyc.push(u);
                steps += 1;
                if steps > 4 * edges.len() + 4 {
                    break;
                }
            }
            let pts: Vec<P> = cyc.iter().map(|i| verts[*i]).collect();
            let comp = root(&mut parent, a);
            by_start.insert(cycles.len(), ());
            cycles.push((cyc, area(&pts), comp));
        }
    }
    (verts, cycles)
}

