    for a in 0..ends.len() {
        let (i, at_start, p) = ends[a];
        if walls[i].arc != 0.0 || !meeting(a).is_empty() {
            continue;
        }
        let mut best: Option<(f64, P)> = None;
        for (j, o) in own.iter().enumerate() {
            let Some(o) = o else { continue };
            if j == i {
                continue;
            }
            let c = &o.centre;
            for k in 0..c.len() - 1 {
                let (s0, s1) = (c[k], c[k + 1]);
                let ab = sub(s1, s0);
                let l2 = dot(ab, ab);
                if l2 < 1e-12 {
                    continue;
                }
                let t = dot(sub(p, s0), ab) / l2;
                if t < 0.0 || t > 1.0 || (k == 0 && t <= 1e-9) || (k == c.len() - 2 && t >= 1.0 - 1e-9) {
                    continue;
                }
                let f = add(s0, mul(ab, t));
                let d = dist(p, f);
                if d <= o.half + 1.0 && best.map(|(bd, _)| d < bd).unwrap_or(true) {
                    best = Some((d, f));
                }
            }
        }
        if let Some((_, f)) = best {
            at[i][if at_start { 0 } else { 1 }] = f;
        }
    }
    let mut outs: Vec<Option<Outline>> = (0..n).map(|i| outline(walls[i], at[i][0], at[i][1])).collect();
    // L joins
    for a in 0..ends.len() {
        let others = meeting(a);
        if others.len() != 1 || others[0] < a || meeting(others[0]).len() != 1 {
            continue;
        }
        let (i, ia, p) = ends[a];
        let (j, jb, _) = ends[others[0]];
        let (Some(oi), Some(oj)) = (&outs[i], &outs[j]) else { continue };
        // each face as seen going out of the joint along its wall: out of a start the left face is
        // on the left, out of an end the right face
        let face_end = |o: &Outline, at_start: bool, left: bool| -> (P, P) {
            let f = if left == at_start { &o.left } else { &o.right };
            if at_start {
                (f[0], mul(o.dir_start, -1.0))
            } else {
                (f[f.len() - 1], o.dir_end)
            }
        };
        let (p1, u1) = face_end(oi, ia, true);
        let (q1, v1) = face_end(oj, jb, false);
        let (p2, u2) = face_end(oi, ia, false);
        let (q2, v2) = face_end(oj, jb, true);
        let (Some(m1), Some(m2)) = (cross_lines(p1, u1, q1, v1), cross_lines(p2, u2, q2, v2)) else { continue };
        // a mitre running far off (walls almost in line) is left out
        let reach = 10.0 * (oi.half + oj.half).max(1.0);
        if dist(m1, p) > reach || dist(m2, p) > reach {
            continue;
        }
        let set = |o: &mut Outline, at_start: bool, outward_left: P, outward_right: P| {
            let (l, r) = if at_start { (&mut o.left, &mut o.right) } else { (&mut o.right, &mut o.left) };
            let li = if at_start { 0 } else { l.len() - 1 };
            let ri = if at_start { 0 } else { r.len() - 1 };
            l[li] = outward_left;
            r[ri] = outward_right;
        };
        if let Some(o) = &mut outs[i] {
            set(o, ia, m1, m2);
        }
        if let Some(o) = &mut outs[j] {
            set(o, jb, m2, m1);
        }
    }
    outs.into_iter().flatten().collect()
}

