"""Random layouts (outer loops, partitions, separators, islands, arcs, levels) built with the
original; load_points on them by both binaries.  usage: sweep_model_rand.py [N] [seed]"""
import sys, json, math, random
sys.path.insert(0, '/tmp/elec-agent')
from rooms_lib import build
from mlib import mbatch, ORIG, MINE

N = int(sys.argv[1]) if len(sys.argv) > 1 else 100
seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
random.seed(seed)
TYPES = ['Generic - 200mm', 'Interior - 100mm', 'Exterior - 300mm']
LOCS = ['centre', 'core-centre', 'exterior-finish', 'interior-finish', 'exterior-core', 'interior-core']
NAMES = ['Sala', 'Quarto', 'Banheiro', 'Cozinha', 'Copa', 'Área de Serviço', 'Lavanderia', 'Varanda', 'Hall', 'Living', 'Kitchen',
         'Bathroom', 'Suíte', 'Closet', 'Escritório', 'Lavabo', 'Dormitório 2', 'Corredor']


def layout():
    cmds = []
    W = random.choice([4000, 5000, 6000, 7500, 8000, 10000, 12000])
    H = random.choice([3000, 4000, 5000, 6000, 8000])
    shape = random.random()
    if shape < 0.6:
        pts = [[0, 0], [W, 0], [W, H], [0, H]]
    elif shape < 0.8:
        a, b = random.choice([0.3, 0.5, 0.6]) * W, random.choice([0.4, 0.5, 0.7]) * H
        pts = [[0, 0], [W, 0], [W, b], [a, b], [a, H], [0, H]]
    else:
        pts = [[0, 0], [W, 0], [W * 0.8, H], [W * 0.1, H * 0.9]]
    if random.random() < 0.3:
        pts = pts[::-1]
    o = {"points": pts, "closed": True, "type": random.choice(TYPES)}
    if random.random() < 0.4:
        o['location'] = random.choice(LOCS)
    if random.random() < 0.3 and len(cmds) == 0:
        # walls one by one instead of a closed run
        for k in range(len(pts)):
            w = {"points": [pts[k], pts[(k + 1) % len(pts)]], "type": o['type']}
            if 'location' in o:
                w['location'] = o['location']
            cmds.append('wall ' + json.dumps(w))
    else:
        cmds.append('wall ' + json.dumps(o))
    # partitions across the rectangle part
    for _ in range(random.choice([0, 1, 1, 2, 3])):
        t = random.choice(TYPES)
        if random.random() < 0.5:
            x = round(random.uniform(0.2, 0.8) * W, random.choice([0, 0, 1]))
            y0 = random.choice([0, 0, 0, 50, 100, 100.5, 150, -100, -300])
            y1 = random.choice([H, H, H, H - 50, H - 100, H * 0.6])
            p = {"points": [[x, y0], [x, y1]], "type": t}
        else:
            y = round(random.uniform(0.2, 0.8) * H, random.choice([0, 0, 1]))
            x0 = random.choice([0, 0, 0, 50, 100, 150, -100])
            x1 = random.choice([W, W, W, W - 100, W * 0.5])
            p = {"points": [[x0, y], [x1, y]], "type": t}
        if random.random() < 0.2:
            p['location'] = random.choice(LOCS)
        if random.random() < 0.1:
            p['height'] = random.choice([1000, 1199, 1201, 2000])
        if random.random() < 0.05:
            p['room_bounding'] = False
        cmds.append('wall ' + json.dumps(p))
    if random.random() < 0.2:
        x = round(random.uniform(0.2, 0.8) * W)
        cmds.append('room_separator ' + json.dumps({"points": [[x, 0], [x, random.choice([H, H * 0.5])]]}))
    if random.random() < 0.15:
        cx, cy = W * 0.5, H * 0.5
        cmds.append('wall ' + json.dumps({"points": [[cx - 500, cy - 300], [cx + 500, cy - 300], [cx + 500, cy + 300], [cx - 500, cy + 300]], "closed": True, "type": "Interior - 100mm"}))
    if random.random() < 0.1:
        cmds.append('wall ' + json.dumps({"points": [[W, 0], [W, H]], "arc": random.choice([30, 60, -40]), "type": random.choice(TYPES)}))
    # rooms
    used = set()
    for _ in range(random.choice([1, 2, 3, 4, 5])):
        q = [round(random.uniform(-0.1, 1.1) * W), round(random.uniform(-0.1, 1.1) * H)]
