data = json.load(open('/tmp/elec-agent/noise4.json'))
HALF = {'Generic - 200mm': 100.0, 'Interior - 100mm': 50.0, 'Exterior - 300mm': 150.0}


def half_of(a, b, r):
    # the wall an edge lies on
    if a[0] == b[0]:
        x = a[0]
        if x == 9000.0:
            return HALF[r['tb']]
        return HALF['Interior - 100mm']  # x = 5400
    y = a[1]
    if y in (0.0, 6000.0):
        return HALF[r['tb']]
    return HALF[r['tp']]


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def add(a, b):
    return (a[0] + b[0], a[1] + b[1])


def mul(a, k):
    return (a[0] * k, a[1] * k)


def unit(v):
    l = math.sqrt(v[0] * v[0] + v[1] * v[1])
    return (v[0] / l, v[1] / l)


def variants():
    for lineq in ['start', 'end']:
        for dirk in ['unit', 'vec']:
            for normk in ['rot_unit', 'vec_div']:
                for inter in ['t1', 't2', 'cramer2pt', 'normal']:
                    yield (lineq, dirk, normk, inter)


def offset_line(a, b, d, lineq, dirk, normk):
    v = sub(b, a)
    u = unit(v)
    if normk == 'rot_unit':
        n = (-u[1], u[0])
        off = mul(n, d)
    else:
        l = math.sqrt(v[0] * v[0] + v[1] * v[1])
        off = (-v[1] * d / l, v[0] * d / l)
    q = add(a if lineq == 'start' else b, off)
    D = u if dirk == 'unit' else v
    return q, D, add(a, off), add(b, off)


def intersect(l1, l2, inter):
    q1, d1, a1, b1 = l1
    q2, d2, a2, b2 = l2
    if inter == 't1':
        t = cross(sub(q2, q1), d2) / cross(d1, d2)
        return add(q1, mul(d1, t))
    if inter == 't2':
        s = cross(sub(q1, q2), d1) / cross(d2, d1)
        return add(q2, mul(d2, s))
    if inter == 'cramer2pt':
        x1, y1 = a1
        x2, y2 = b1
        x3, y3 = a2
        x4, y4 = b2
        D = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
        px = ((x1 * y2 - y1 * x2) * (x3 - x4) - (x1 - x2) * (x3 * y4 - y3 * x4)) / D
        py = ((x1 * y2 - y1 * x2) * (y3 - y4) - (y1 - y2) * (x3 * y4 - y3 * x4)) / D
        return (px, py)
    if inter == 'normal':
        n1 = (-d1[1], d1[0])
        n2 = (-d2[1], d2[0])
        c1 = n1[0] * q1[0] + n1[1] * q1[1]
        c2 = n2[0] * q2[0] + n2[1] * q2[1]
        det = n1[0] * n2[1] - n1[1] * n2[0]
        return ((c1 * n2[1] - c2 * n1[1]) / det, (n1[0] * c2 - n2[0] * c1) / det)


