def on(w, a, b):
    s, e, _ = w
    # both a and b on the wall's line (axis aligned here)
    if s[0] == e[0]:
        return abs(a[0] - s[0]) < 1e-6 and abs(b[0] - s[0]) < 1e-6
    return abs(a[1] - s[1]) < 1e-6 and abs(b[1] - s[1]) < 1e-6


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def add(a, b):
    return (a[0] + b[0], a[1] + b[1])


def mul(a, k):
    return (a[0] * k, a[1] * k)


def line(r, a, b, mode):
    """the offset line of the edge a->b (room on its left): two points."""
    w = [w for w in walls_of(r) if on(w, a, b)][0]
    d = w[2]
    v = sub(b, a)
    l = math.sqrt(v[0] ** 2 + v[1] ** 2)
    n = (-v[1] / l, v[0] / l)
    off = mul(n, d)
    if mode == 'piece':
        return add(a, off), add(b, off)
    s, e = w[0], w[1]
    same = (e[0] - s[0]) * v[0] + (e[1] - s[1]) * v[1] > 0
    if mode == 'wall_own':
        return add(s, off), add(e, off)
    if mode == 'wall_trav':
        return (add(s, off), add(e, off)) if same else (add(e, off), add(s, off))


def inter(l1, l2, which):
    s1, e1 = l1
    s2, e2 = l2
    d1, d2 = sub(e1, s1), sub(e2, s2)
    if which == 1:
