usage: kept_cmp.py file_with_layouts.json  (a list of [commands, [points]])"""
import sys, json, subprocess, os, tempfile, shutil
sys.path.insert(0, '/tmp/elec-agent')
from rooms_lib import build, ORIG, MINE


def kept_polys(cmds, pts):
    c = ['room_area {"at": "finish"}'] + cmds + ['room {"point": [%r, %r], "name": "R%d", "frozen": true}' % (p[0], p[1], i) for i, p in enumerate(pts)]
    build(c, '/tmp/elec-agent/kc_o.bimcraft')
    d = json.load(open('/tmp/elec-agent/kc_o.bimcraft'))
    out = []
    for v in d['elements'].values():
        if v['category'] == 'room':
            out.append(v.get('kept', {}).get('finish', {}).get('outer'))
    return out


def mine_polys(cmds, pts):
    c = cmds + ['room {"point": [%r, %r], "name": "R%d"}' % (p[0], p[1], i) for i, p in enumerate(pts)]
    build(c, '/tmp/elec-agent/kc_m.bimcraft')
    d = tempfile.mkdtemp()
    shutil.copy('/tmp/elec-agent/kc_m.bimcraft', d)
    env = dict(os.environ, ROOMS_DEBUG='1')
    p = subprocess.run([MINE, 'run', 'kc_m.bimcraft', '--cmd', 'load_points {}'], cwd=d, capture_output=True, text=True, env=env)
    shutil.rmtree(d)
    out = []
    for line in p.stderr.split('\n'):
        if line.startswith('outer '):
            out.append(json.loads(line[6:]))
    return out


if __name__ == '__main__':
    layouts = json.load(open(sys.argv[1]))
    same = diff = 0
    for cmds, pts in layouts:
        try:
            a = kept_polys(cmds, pts)
            b = mine_polys(cmds, pts)
        except Exception as e:
            print('ERR', str(e)[:200])
            continue
        if a == b:
            same += 1
        else:
            diff += 1
            if diff <= 6:
                print('LAYOUT', json.dumps(cmds)[:600])
                for x, y in zip(a, b):
                    if x != y:
                        print('  ORIG', [[repr(c) for c in p] for p in (x or [])])
                        print('  MINE', [[repr(c) for c in p] for p in (y or [])])
    print('kept polygons: %d same, %d differ' % (same, diff))

