        a, b = random.choice([0.4, 0.5, 0.6]) * W, random.choice([0.4, 0.5]) * H
        pts = [[0, 0], [W, 0], [W, b], [a, b], [a, H], [0, H]]
    elif shape == 'U':
        a1, a2, b = 0.3 * W, 0.7 * W, 0.5 * H
        pts = [[0, 0], [W, 0], [W, H], [a2, H], [a2, b], [a1, b], [a1, H], [0, H]]
    elif shape == 'slant':
        pts = [[0, 0], [W, 0], [W, H * 0.7], [W * 0.6, H], [0, H]]
    else:
        pts = [[0, 0], [W, 0], [W, H], [0, H]]
    if random.random() < 0.3:
        pts = pts[::-1]
    loc = random.choice(LOCS) if random.random() < 0.3 else 'centre'
    t = random.choice(TYPES)
    cmds = []
    if random.random() < 0.6:
        cmds.append('wall ' + json.dumps({"points": pts, "closed": True, "type": t, "location": loc}))
    else:
        for k in range(len(pts)):
            cmds.append('wall ' + json.dumps({"points": [pts[k], pts[(k + 1) % len(pts)]], "type": random.choice(TYPES), "location": loc}))
    rooms = []
    if shape == 'rect':
        nx, ny = random.choice([1, 2, 3]), random.choice([1, 2])
        xs = [W * k / nx for k in range(1, nx)]
        ys = [H * k / ny for k in range(1, ny)]
        for x in xs:
            cmds.append('wall ' + json.dumps({"points": [[x, 0], [x, H]], "type": random.choice(TYPES)}))
        for y in ys:
            if random.random() < 0.3:
                cmds.append('room_separator ' + json.dumps({"points": [[0, y], [W, y]]}))
            else:
                cmds.append('wall ' + json.dumps({"points": [[0, y], [W, y]], "type": random.choice(TYPES)}))
        for i in range(nx):
            for j in range(ny):
                rooms.append([W * (i + 0.5) / nx, H * (j + 0.5) / ny])
    elif shape == 'L':
        rooms = [[W * 0.2, H * 0.2]]
        if random.random() < 0.5:
            cmds.append('wall ' + json.dumps({"points": [[a, 0], [a, b]], "type": random.choice(TYPES)}))
            rooms = [[a * 0.5, H * 0.3], [(a + W) / 2, b / 2]]
    elif shape == 'U':
        rooms = [[W * 0.5, H * 0.25]]
    else:
        rooms = [[W * 0.4, H * 0.4]]
    res.append([cmds, [[round(q[0]), round(q[1])] for q in rooms]])
json.dump(res, open(out, 'w'))

